const termDefinitions = {
    // A
    'Acción': { definition: 'Título que representa una parte proporcional del capital social de una empresa.', example: 'Si compras una acción de Apple, eres dueño de una pequeña parte de la compañía.' },
    'Activo': { definition: 'Bien o derecho que posee una persona o empresa y que puede generar beneficios futuros.', example: 'Una casa, un coche o dinero en el banco são ejemplos de activos.' },
    'Ahorro': { definition: 'Parte del ingreso que no se gasta y se reserva para necesidades futuras.', example: 'Guardar el 10% de tu salario cada mes é uma buena práctica de ahorro.' },
    'Amortización': { definition: 'Proceso de pago gradual de una deuda o la pérdida de valor de un activo com el tiempo.', example: 'La amortización de tu hipoteca dura 30 años.' },
    'Arancel': { definition: 'Impuesto que se aplica a los bienes que se importan o exportan.', example: 'El gobierno impuso un arancel del 20% al acero extranjero.' },
    'Auditoría': { definition: 'Revisión sistemática de las cuentas y estados financieros de una empresa.', example: 'Una auditoría externa confirmó que las cuentas de la empresa eran correctas.' },
    'Apalancamiento': { definition: 'Uso de deuda para financiar una operación com la esperanza de que la rentabilidad sea superior al costo del interés.', example: 'El apalancamiento puede multiplicar las ganancias, pero también las pérdidas.' },
    'Asignación de Activos': { definition: 'Estrategia de inversión que equilibra el riesgo y la recompensa mediante la repartición de los activos de una cartera.', example: 'Una asignación de activos común é um 60% en acciones y un 40% en bonos.' },
    'Aceptación': { definition: 'Compromiso de pagar una letra de cambio a su vencimiento.', example: 'El banco dio su aceptación al pago de la exportación.' },
    'Adquisición': { definition: 'Compra de una empresa o de una participación mayoritaria en ella.', example: 'La adquisición de la startup tecnológica fortaleció la posición de la gran empresa.' },
    'Aduana': { definition: 'Oficina pública estatal encargada de registrar los bienes que entran o salen de un país y de cobrar los impuestos correspondientes.', example: 'Tuvimos que declarar los productos importados en la aduana del puerto.' },
    'Afiliado': { definition: 'Persona o entidad que forma parte de una organización o sistema.', example: 'El sindicato tiene más de mil afiliados en esta ciudad.' },
    'Agencia': { definition: 'Empresa que presta servicios de mediación o representación.', example: 'Contratamos una agencia de marketing para mejorar nuestra imagen.' },
    'Agente': { definition: 'Persona que actúa en nombre de otra o de una entidad.', example: 'El agente de seguros me explicó todas las coberturas de la póliza.' },
    'Ajuste': { definition: 'Corrección de valores o precios para reflejar la realidad económica o fiscal.', example: 'El gobierno anunció un ajuste en las tarifas eléctricas.' },
    'Alquiler': { definition: 'Precio que se paga por el uso temporal de un bien.', example: 'El alquiler de la oficina subió un 5% este año.' },
    'Análisis': { definition: 'Examen detallado de una situación o datos para entender su comportamiento.', example: 'El análisis financiero muestra que la empresa es solvente.' },
    'Analista': { definition: 'Profesional especializado en el estudio de mercados o empresas.', example: 'El analista de riesgos recomendó no invertir en ese sector.' },
    'Anticipo': { definition: 'Pago que se realiza antes de la entrega de bienes o servicios.', example: 'Pedimos un anticipo del 20% para empezar el proyecto.' },
    'Anualidad': { definition: 'Serie de pagos o ingresos iguales realizados a intervalos regulares durante un periodo determinado.', example: 'Recibe una anualidad de su plan de pensiones privado.' },
    'Apreciación': { definition: 'Aumento del valor de un bien o moneda respecto a otros.', example: 'La apreciación del euro favorece a los que viajan a Estados Unidos.' },
    'Arbitraje': { definition: 'Práctica de aprovechar la diferencia de precio entre dos o más mercados para obtener un beneficio sin riesgo.', example: 'El arbitraje financiero permite ganar dinero comprando barato en Londres y vendiendo caro en Nueva York.' },
    'Asesor': { definition: 'Experto que ofrece consejos o información técnica sobre una materia.', example: 'El asesor fiscal nos ayudó a optimizar el pago de impuestos.' },
    'Asignación': { definition: 'Distribución de recursos escasos entre diferentes usos o destinatarios.', example: 'La asignación de fondos para investigación aumentó significativamente.' },
    'Atraso': { definition: 'Retraso en el cumplimiento de una obligación, especialmente de pago.', example: 'El atraso en el pago de la deuda generó intereses de demora.' },
    'Auge': { definition: 'Fase del ciclo económico de máximo crecimiento y actividad.', example: 'Durante el auge inmobiliario se construyeron miles de viviendas.' },
    'Autarquía': { definition: 'Sistema económico en el que un país busca ser autosuficiente y evita el comercio com el exterior.', example: 'La autarquía suele llevar al estancamiento económico por falta de competencia.' },
    'Aval': { definition: 'Garantía que una persona o entidad presta para asegurar el cumplimiento de una obligación por parte de un tercero.', example: 'Mis padres actuaron como aval para que me concedieran el préstamo.' },
    'Aversión al Riesgo': { definition: 'Preferencia de un inversor por evitar la incertidumbre a costa de menores rentabilidades.', example: 'Su alta aversión al riesgo le hace invertir solo en depósitos garantizados.' },
    'Activo Financiero': { definition: 'Título o derecho que otorga a su poseedor el derecho a recibir ingresos futuros por parte del emisor.', example: 'Las acciones y los bonos são los activos financieros más comunes.' },
    'Acuñación': { definition: 'Marcado de piezas de metal para convertirlas en moneda legal.', example: 'La acuñación de nuevas monedas de euro se realiza en la Casa de la Moneda.' },
    'Ad Valorem': { definition: 'Impuesto o tasa que se calcula como un porcentaje del valor del bien.', example: 'El arancel ad valorem del 10% se aplica sobre el precio de factura.' },
    'Agregados Monetarios': { definition: 'Indicadores que miden la cantidad de dinero que circula en una economía (M1, M2, M3).', example: 'El Banco Central vigila la evolución de los agregados monetarios para controlar la inflación.' },
    'Ahorro Bruto': { definition: 'Total de la renta no consumida antes de descontar la depreciación de los activos.', example: 'El ahorro bruto nacional es fundamental para financiar la inversión.' },
    'Ahorro Neto': { definition: 'Ahorro bruto tras deducir el consumo de capital fijo (depreciación).', example: 'El ahorro neto muestra el crecimiento real de la riqueza de un país.' },

    // B
    'Balance': { definition: 'Documento contable que muestra la situación financiera de una empresa en un momento dado.', example: 'El balance general muestra los activos y pasivos de la compañía.' },
    'Banco': { definition: 'Institución financiera que acepta depósitos y otorga préstamos.', example: 'Deposité mi cheque en el banco para mantenerlo seguro.' },
    'Banco Central': { definition: 'Entidad que gestiona la moneda y la política monetaria de un país o región.', example: 'El Banco Central Europeo decidió subir los tipos de interés para controlar la inflación.' },
    'Beneficio': { definition: 'Ganancia económica que se obtiene de un negocio o inversión tras descontar los gastos.', example: 'La empresa reportó un beneficio neto de 1 millón de dólares.' },
    'Bolsa de Valores': { definition: 'Mercado donde se compran y venden acciones y otros instrumentos financieros.', example: 'Las acciones de tecnología subieron hoy en la Bolsa de Nueva York.' },
    'Bono': { definition: 'Título de deuda emitido por empresas o gobiernos para financiarse.', example: 'Compré un bono del estado que paga un 3% de interés anual.' },
    'Burbuja': { definition: 'Situación en la que los precios de los activos suben muy por encima de su valor real.', example: 'La burbuja inmobiliaria estalló y los precios de las casas cayeron.' },
    'Backlog': { definition: 'Acumulación de trabajo pendiente o pedidos no servidos.', example: 'La empresa tiene un backlog de seis meses en la entrega de sus productos.' },
    'Bancarrota': { definition: 'Situación legal de una persona o empresa que no puede pagar sus deudas (quiebra).', example: 'La aerolínea se declaró en bancarrota tras la caída del turismo.' },
    'Balanza Comercial': { definition: 'Registro de las exportaciones e importaciones de mercancías de un país.', example: 'El país tiene una balanza comercial positiva porque exporta más de lo que importa.' },
    'Balanza de Pagos': { definition: 'Documento contable que registra todas las transacciones económicas de un país com el exterior.', example: 'La balanza de pagos incluye el comercio de bienes, servicios y flujos de capital.' },
    'Balanza Financiera': { definition: 'Parte de la balanza de pagos que registra las inversiones y préstamos de un país com el exterior.', example: 'La balanza financiera mostró una salida de capitales hacia mercados más seguros.' },
    'Banca de Inversión': { definition: 'Entidad financiera que ayuda a las empresas a obtener capital y ofrece asesoramiento en fusiones.', example: 'La banca de inversión gestionó la salida a bolsa de la red social.' },
    'Banca Privada': { definition: 'Servicio financiero personalizado para clientes com un alto patrimonio neto.', example: 'La banca privada ofrece soluciones de inversión exclusivas y planificación fiscal.' },
    'Base Imponible': { definition: 'Cantidad de dinero sobre la que se calcula el importe de un impuesto.', example: 'Tras aplicar las deducciones, la base imponible del IRPF resultó menor.' },
    'Base Monetaria': { definition: 'Total de dinero efectivo en manos del público y reservas bancarias.', example: 'El Banco Central inyectó liquidez aumentando la base monetaria.' },
    'Bear Market': { definition: 'Mercado bajista, caracterizado por una caída sostenida de los precios y pesimismo de los inversores.', example: 'En un bear market, los inversores suelen vender para evitar mayores pérdidas.' },
    'Benchmark': { definition: 'Punto de referencia que se utiliza para comparar el rendimiento de una inversión.', example: 'El S&P 500 es el benchmark habitual para los fondos de acciones estadounidenses.' },
    'Beneficiario': { definition: 'Persona que tiene derecho a recibir una prestación o los fondos de un contrato.', example: 'Designó a su esposa como beneficiaria del seguro de vida.' },
    'Beneficios Retenidos': { definition: 'Parte del beneficio neto que una empresa decide no repartir como dividendos y reinvertir.', example: 'La empresa financió el nuevo laboratorio com sus beneficios retenidos.' },
    'Beta': { definition: 'Medida de la volatilidad de un activo en relación com el mercado general.', example: 'Una acción con una beta superior a 1 es más volátil que la media del mercado.' },
    'Bien de Consumo': { definition: 'Producto fabricado para satisfacer directamente las necesidades del consumidor final.', example: 'La televisión y la ropa são ejemplos típicos de bienes de consumo.' },
    'Bien de Capital': { definition: 'Bien duradero que se utiliza en el proceso de producción de otros bienes o servicios.', example: 'La maquinaria pesada de la fábrica é um bien de capital esencial.' },
    'Bien Público': { definition: 'Bien cuyo consumo no es excluyente y no disminuye por el uso de otras personas.', example: 'El alumbrado de las calles y la defensa nacional são bienes públicos.' },
    'Billete': { definition: 'Papel moneda de curso legal emitido por el Banco Central.', example: 'Llevo un billete de 20 euros para comprar el pan.' },
    'Blue Chip': { definition: 'Empresa consolidada, com ingresos estables y líder en su sector.', example: 'Telefónica y Santander são consideradas blue chips en el mercado español.' },
    'Bonificación': { definition: 'Descuento o aumento de una cantidad por razones específicas.', example: 'Recibí una bonificación por buen rendimiento en mi trabajo.' },
    'Boom': { definition: 'Expansión económica rápida y acentuada.', example: 'El boom de las empresas punto com terminó com la caída del Nasdaq.' },
    'Broker': { definition: 'Corredor que actúa como intermediario en las operaciones de compra y venta de activos.', example: 'Mi broker online me cobra comisiones muy bajas por operar en bolsa.' },
    'Bull Market': { definition: 'Mercado alcista, caracterizado por el optimismo y la subida de precios.', example: 'El sector tecnológico ha vivido un bull market prolongado en la última década.' },
    'Business-to-Business (B2B)': { definition: 'Modelo de negocio que se centra en las transacciones entre empresas.', example: 'Nuestra empresa de software opera principalmente en el sector B2B.' },
    'Business-to-Consumer (B2C)': { definition: 'Modelo de negocio en el que las empresas venden directamente al consumidor final.', example: 'Amazon es el mayor ejemplo de éxito en el comercio B2C.' },

    // C
    'Capital': { definition: 'Recursos financieros o bienes que se utilizan para generar riqueza.', example: 'Necesitas capital inicial para abrir tu propio negocio.' },
    'Capitalización de Mercado': { definition: 'Valor total de mercado de las acciones en circulación de una empresa.', example: 'Apple tiene una de las mayores capitalizaciones de mercado del mundo.' },
    'Ciclo Económico': { definition: 'Fluctuaciones recurrentes en la actividad económica (auge, recesión, depresión, recuperación).', example: 'Actualmente estamos en una fase de expansión del ciclo económico.' },
    'Cobertura': { definition: 'Estrategia financiera para reducir el riesgo de pérdidas en inversiones.', example: 'La empresa compró opciones como cobertura contra la caída del precio del petróleo.' },
    'Comisión': { definition: 'Tarifa que se paga a un agente o intermediario por realizar una transacción.', example: 'El agente inmobiliario cobra una comisión del 3% por vender la casa.' },
    'Consumo': { definition: 'Gasto de las familias en bienes y servicios para satisfacer sus necesidades.', example: 'El consumo aumenta durante la temporada navideña.' },
    'Costo de Oportunidad': { definition: 'El valor de la mejor alternativa a la que renuncias cuando tomas una decisión.', example: 'El costo de oportunidad de estudiar esta tarde es no poder ir al cine.' },
    'Crédito': { definition: 'Préstamo de dinero que una parte otorga a otra com el compromiso de devolución futura.', example: 'Pagué la cena con tarjeta de crédito y la saldaré a fin de mes.' },
    'Criptomoneda': { definition: 'Moneda digital que utiliza criptografía para asegurar transacciones.', example: 'Bitcoin es la criptomoneda más conocida del mundo.' },
    'Cadena de Suministro': { definition: 'Red de personas y empresas involucradas en la creación y distribución de un producto.', example: 'La crisis de los chips afectó a la cadena de suministro de automóviles.' },
    'Caja': { definition: 'Dinero en efectivo disponible en una empresa o lugar donde se realizan cobros.', example: 'Hicimos el arqueo de caja al final de la jornada laboral.' },
    'Cajero Automático': { definition: 'Máquina que permite realizar operaciones bancarias de forma autónoma.', example: 'Saqué dinero del cajero automático usando mi tarjeta de débito.' },
    'Calificación Crediticia': { definition: 'Evaluación de la solvencia de una persona o entidad para pagar sus deudas.', example: 'Su excelente calificación crediticia le permitió obtener una hipoteca a bajo interés.' },
    'Cámara de Compensación': { definition: 'Institución donde los bancos liquidan sus pagos y cobros mutuos.', example: 'Los cheques se liquidan diariamente a través de la cámara de compensación.' },
    'Canje': { definition: 'Intercambio de un bien o valor por otro.', example: 'El canje de bonos antiguos por otros nuevos fue aceptado por los inversores.' },
    'Canon': { definition: 'Pago periódico que se realiza por el uso de un derecho o servicio.', example: 'La empresa paga un canon anual por la explotación de la marca.' },
    'Capacidad Adquisitiva': { definition: 'Cantidad de bienes y servicios que pueden comprarse com una suma de dinero.', example: 'La inflación reduce la capacidad adquisitiva de los trabajadores.' },
    'Capital de Trabajo': { definition: 'Recursos financieros que una empresa necesita para operar en el día a día.', example: 'Tenemos suficiente capital de trabajo para cubrir los gastos de este mes.' },
    'Capital Riesgo': { definition: 'Inversión en empresas jóvenes o com alto potencial de crecimiento pero con incertidumbre.', example: 'El capital riesgo fue fundamental para el lanzamiento de la nueva app.' },
    'Capital Social': { definition: 'Valor total de las aportaciones de los socios a una empresa.', example: 'Los socios fundadores aportaron 50.000 euros en concepto de capital social.' },
    'Capitalismo': { definition: 'Sistema económico basado en la propiedad privada de los medios de producción y el libre mercado.', example: 'El capitalismo fomenta la competencia y la innovación empresarial.' },
    'Cártel': { definition: 'Acuerdo ilegal entre empresas para controlar precios y eliminar la competencia.', example: 'La comisión de competencia multó al cártel de las constructoras.' },
    'Cartera de Inversión': { definition: 'Conjunto de activos financieros que posee una persona o entidad.', example: 'Mi cartera de inversión incluye acciones, bonos y algo de oro.' },
    'Cash Flow': { definition: 'Flujo de caja; diferencia entre las entradas y salidas de efectivo.', example: 'El cash flow positivo es vital para la supervivencia de la empresa.' },
    'Cédula Hipotecaria': { definition: 'Valor de renta fija emitido por una entidad financiera y garantizado por sus hipotecas.', example: 'Invertí en cédulas hipotecarias por su seguridad y rentabilidad estable.' },
    'Certificado de Depósito': { definition: 'Título que acredita la existencia de un depósito de dinero a plazo fijo.', example: 'Contraté un certificado de depósito a seis meses com un 3% de interés.' },
    'Cheque': { definition: 'Orden de pago escrita que permite retirar dinero de una cuenta bancaria.', example: 'Pagué el coche com un cheque conformado por el banco.' },
    'Ciclo de Vida': { definition: 'Etapas por las que pasa un producto o empresa desde su creación hasta su desaparición.', example: 'El producto está en su etapa de madurez dentro de su ciclo de vida.' },
    'Cierre': { definition: 'Finalización de las operaciones contables o de mercado de un periodo.', example: 'El cierre de la bolsa hoy fue ligeramente al alza.' },
    'CIF': { definition: 'Código de Identificación Fiscal; identificación de personas jurídicas en España.', example: 'Necesitamos el CIF de su empresa para emitir la factura legal.' },
    'Cláusula': { definition: 'Disposición particular de un contrato o documento legal.', example: 'La cláusula de rescisión del contrato es muy elevada.' },
    'Clientela': { definition: 'Conjunto de personas que compran habitualmente en un establecimiento o servicio.', example: 'Nuestra clientela es fiel y valora mucho la calidad del servicio.' },
    'Cobertura de Riesgo': { definition: 'Estrategia para protegerse contra posibles pérdidas financieras.', example: 'Contratamos un seguro como cobertura de riesgo ante incendios.' },
    'Coeficiente de Caja': { definition: 'Porcentaje de los depósitos que los bancos deben mantener como reserva legal.', example: 'El Banco Central subió el coeficiente de caja para reducir la masa monetaria.' },
    'Colateral': { definition: 'Garantía adicional que se ofrece para asegurar el pago de un préstamo.', example: 'Utilizó sus acciones como colateral para obtener el crédito.' },
    'Colocación': { definition: 'Venta de valores financieros entre el público o inversores.', example: 'La colocación de la nueva emisión de deuda fue un éxito total.' },
    'Comercio Exterior': { definition: 'Intercambio de bienes y servicios entre distintos países.', example: 'El comercio exterior es el motor de la economía de muchos países en desarrollo.' },
    'Comodity': { definition: 'Materia Prima; bien básico que se utiliza en el comercio y es intercambiable.', example: 'El petróleo y el trigo são las commodities más negociadas del mundo.' },
    'Compañía': { definition: 'Sociedad o unión de personas com fines empresariales.', example: 'Trabajo en una compañía multinacional de tecnología.' },
    'Compensación': { definition: 'Acción de equilibrar una deuda com un crédito, o indemnización por un daño.', example: 'Los bancos realizan la compensación de sus saldos al final del día.' },
    'Competencia Desleal': { definition: 'Prácticas comerciales éticamente cuestionables para ganar ventaja frente a rivales.', example: 'Fue demandado por competencia desleal al utilizar información confidencial.' },
    'Competencia Perfecta': { definition: 'Situación teórica de mercado donde hay muchos compradores y vendedores y nadie influye en el precio.', example: 'El mercado de productos agrícolas se aproxima al modelo de competencia perfecta.' },
    'Compravento': { definition: 'Contrato por el que uno vende una cosa y otro la compra por un precio.', example: 'Firmamos el contrato de compraventa ante el notario.' },
    'Comprobante': { definition: 'Documento que sirve para acreditar una transacción o gasto.', example: 'Guarde el comprobante de pago por si necesita hacer una reclamación.' },
    'Comunidad Económica': { definition: 'Asociación de países para fomentar el comercio y la integración entre ellos.', example: 'La Comunidad Económica Europea fue el origen de la actual Unión Europea.' },
    'Concesión': { definition: 'Derecho otorgado por una autoridad para explotar un servicio o recurso público.', example: 'La empresa obtuvo la concesión para gestionar el túnel de peaje.' },
    'Condiciones de Pago': { definition: 'Términos acordados sobre cuándo y cómo se abonará una deuda.', example: 'Nuestras condiciones de pago são a 30 días fecha factura.' },
    'Confederación': { definition: 'Unión de asociaciones, sindicatos o estados com intereses comunes.', example: 'La confederación de empresarios pidió una reducción de las cuotas sociales.' },
    'Confianza del Consumidor': { definition: 'Indicador económico que mide el optimismo o pesimismo de los consumidores sobre su situación financiera.', example: 'El aumento de la confianza del consumidor suele preceder a un incremento del gasto.' },
    'Conglomerado': { definition: 'Grupo de empresas com actividades muy diversas que pertenecen a una misma organización.', example: 'El conglomerado coreano tiene divisiones de electrónica, construcción y finanzas.' },
    'Concurso de Acreedores': { definition: 'Procedimiento legal cuando una empresa no puede pagar sus deudas y busca un acuerdo o liquidación.', example: 'La constructora solicitó el concurso de acreedores para evitar el cierre inmediato.' },
    'Consolidación': { definition: 'Proceso de agrupar estados financieros de varias empresas o reducción de deuda.', example: 'La consolidación bancaria redujo el número de entidades en el país.' },
    'Consorcio': { definition: 'Agrupación de empresas para llevar a cabo un proyecto común de gran envergadura.', example: 'El consorcio internacional ganó la licitación para construir el nuevo aeropuerto.' },
    'Consumismo': { definition: 'Tendencia al consumo excesivo e innecesario de bienes y servicios.', example: 'El consumismo desenfrenado genera una gran cantidad de residuos ambientales.' },
    'Contabilidad': { definition: 'Sistema de registro y control de todos los movimientos económicos de una empresa.', example: 'Llevar la contabilidad al día es fundamental para la toma de decisiones.' },
    'Contador': { definition: 'Profesional encargado de llevar los registros financieros y la fiscalidad de una entidad.', example: 'El contador me ayudó a preparar la declaración de impuestos anual.' },
    'Contrato': { definition: 'Acuerdo legal entre dos o más partes que genera obligaciones y derechos.', example: 'Firmé un contrato de trabajo indefinido com mi nueva empresa.' },
    'Contribución': { definition: 'Pago obligatorio al estado o participación en un gasto común.', example: 'La contribución a la seguridad social es obligatoria para todos los trabajadores.' },
    'Control de Cambios': { definition: 'Medida estatal que restringe la compra y venta de moneda extranjera.', example: 'El gobierno impuso un control de cambios para frenar la fuga de capitales.' },
    'Control de Precios': { definition: 'Intervención del gobierno para fijar el precio máximo o mínimo de ciertos bienes.', example: 'El control de precios del alquiler busca facilitar el acceso a la vivienda.' },
    'Convergencia': { definition: 'Proceso por el cual las economías de diferentes países tienden a parecerse o unirse.', example: 'Los países de la UE deben cumplir criterios de convergencia para usar el euro.' },
    'Convertibilidad': { definition: 'Capacidad de una moneda para ser intercambiada por otra o por oro sin restricciones.', example: 'La convertibilidad del peso uno a uno com el dólar terminó en crisis económica.' },
    'Cooperativa': { definition: 'Sociedad formada por productores, vendedores o consumidores para beneficio común.', example: 'La cooperativa agrícola permite a los pequeños agricultores vender a mejor precio.' },
    'Corredor de Bolsa': { definition: 'Persona o entidad autorizada para comprar y vender valores en el mercado bursátil.', example: 'Llamé a mi corredor de bolsa para comprar acciones de la tecnológica.' },
    'Corretaje': { definition: 'Comisión que percibe un corredor por su intervención en un negocio.', example: 'El corretaje de la operación inmobiliaria fue del 5% del valor de venta.' },
    'Corto Plazo': { definition: 'Periodo de tiempo breve, generalmente inferior a un año.', example: 'Necesitamos financiación a corto plazo para pagar a los proveedores.' },
    'Coste de Producción': { definition: 'Suma de los gastos necesarios para fabricar un bien o servicio.', example: 'La automatización permitió reducir el coste de producción por unidad.' },
    'Coste Fijo': { definition: 'Gasto que no varía aunque cambie el nivel de producción de la empresa.', example: 'El alquiler de la nave é um coste fijo que debemos pagar cada mes.' },
    'Coste Marginal': { definition: 'Incremento del coste total al producir una unidad adicional.', example: 'La empresa produce más mientras el ingreso marginal sea superior al coste marginal.' },
    'Coste Variable': { definition: 'Gasto que cambia en proporción directa al volumen de producción.', example: 'La materia prima es el principal coste variable de la panadería.' },
    'Coyuntura': { definition: 'Conjunto de circunstancias que caracterizan la situación económica en un momento dado.', example: 'La coyuntura actual es favorable para la expansión internacional.' },
    'Crecimiento Económico': { definition: 'Aumento sostenido de la producción de bienes y servicios de un país.', example: 'El crecimiento económico permitió mejorar los servicios públicos.' },
    'Credencial': { definition: 'Documento que acredita la identidad o autoridad de alguien en un ámbito.', example: 'El auditor presentó sus credenciales antes de empezar la revisión.' },
    'Crédito Documentario': { definition: 'Instrumento de pago internacional donde un banco garantiza el pago al vendedor.', example: 'El exportador exigió un crédito documentario irrevocable para enviar la mercancía.' },
    'Crédito Hipotecario': { definition: 'Préstamo garantizado por un inmueble para la compra de vivienda o local.', example: 'Solicité un crédito hipotecario a tipo fijo para evitar sorpresas.' },
    'Crisis Económica': { definition: 'Periodo de recesión profunda com caída notable del PIB y aumento del paro.', example: 'La crisis económica de 2008 afectó a casi todos los países del mundo.' },
    'Cronograma': { definition: 'Calendario detallado de actividades o pagos de un proyecto.', example: 'Debemos seguir el cronograma para terminar la obra a tiempo.' },
    'Cuantía': { definition: 'Importe o valor de un pago, deuda o subvención.', example: 'La cuantía de la beca depende de los ingresos familiares.' },
    'Cuenta Corriente': { definition: 'Contrato bancario que permite ingresos y pagos inmediatos y disposición de fondos.', example: 'Uso mi cuenta corriente para pagar los recibos del hogar.' },
    'Cuenta de Resultados': { definition: 'Documento que resume los ingresos y gastos de una empresa y muestra su beneficio o pérdida.', example: 'La cuenta de resultados del año pasado mostró un crecimiento del 10%.' },
    'Cuota de Mercado': { definition: 'Porcentaje de ventas de una empresa respecto al total del mercado.', example: 'Nuestra marca tiene una cuota de mercado del 25% en el sector.' },
    'Cupón': { definition: 'Interés periódico que paga un bono u otro título de renta fija.', example: 'El cupón del 5% se abona semestralmente a los tenedores del bono.' },

    // D
    'Déficit': { definition: 'Situación en la que los gastos superan a los ingresos.', example: 'El gobierno tiene un déficit fiscal porque gastó más de lo que recaudó.' },
    'Deflación': { definition: 'Caída generalizada y prolongada de los precios de bienes y servicios.', example: 'Durante la deflación, tu dinero vale más porque los precios bajan.' },
    'Demanda': { definition: 'Cantidad de bienes o servicios que los consumidores están dispuestos a comprar.', example: 'La demanda de aire acondicionado sube en verano.' },
    'Depósito': { definition: 'Dinero entregado a una entidad financiera para su custodia o ahorro.', example: 'Abrí un depósito a plazo fijo que me da intereses anuales.' },
    'Depreciación': { definition: 'Pérdida de valor de un activo debido al uso, paso del tiempo u obsolescencia.', example: 'Un coche sufre depreciación nada más salir del concesionario.' },
    'Derivado': { definition: 'Producto financiero cuyo valor depende de otro activo subyacente.', example: 'Los futuros del oro são un derivado financiero.' },
    'Deuda': { definition: 'Obligación de pagar dinero a otra parte.', example: 'Tengo una deuda estudiantil que terminaré de pagar en 5 años.' },
    'Diversificación': { definition: 'Técnica de reducción de riesgo que mezcla una variedad de inversiones dentro de una cartera.', example: 'No pongas todos los huevos en la misma cesta; la diversificación es clave.' },
    'Dividendo': { definition: 'Parte de las ganancias de una empresa que se reparte entre los accionistas.', example: 'Recibí un dividendo trimestral por mis acciones de Coca-Cola.' },
    'Divisa': { definition: 'Moneda extranjera utilizada en el comercio internacional.', example: 'El dólar y el euro são las divisas más negociadas.' },
    'Dación en Pago': { definition: 'Entrega de un bien para saldar una deuda hipotecaria.', example: 'La dación en pago permite entregar la vivienda al banco para cancelar la hipoteca.' },
    'Daño Emergente': { definition: 'Pérdida real y directa sufrida por un patrimonio.', example: 'El seguro cubrió el daño emergente tras el incendio de la fábrica.' },
    'Debe': { definition: 'Columna izquierda de una cuenta contable donde se registran gastos o activos.', example: 'Anota la compra de suministros en el debe de la cuenta.' },
    'Debito': { definition: 'Cargo en una cuenta bancaria o contable.', example: 'El banco realizó un débito automático para el pago de la luz.' },
    'Declaración de Bienes': { definition: 'Documento donde se detallan las posesiones de una persona o entidad.', example: 'Los altos cargos deben presentar una declaración de bienes al asumir su puesto.' },
    'Deducción Fiscal': { definition: 'Cantidad que se resta de la cuota de un impuesto por ciertos gastos.', example: 'La deducción fiscal por inversión en I+D redujo el impuesto de sociedades.' },
    'Deflación de Activos': { definition: 'Caída de los precios de activos como acciones o viviendas.', example: 'La deflación de activos bursátiles preocupó a los grandes fondos.' },
    'Deflactor del PIB': { definition: 'Índice de precios que calcula la inflación de todos los bienes producidos en un país.', example: 'El deflactor del PIB es más amplio que el IPC al incluir bienes de capital.' },
    'Demanda Agregada': { definition: 'Total de bienes y servicios que los agentes económicos están dispuestos a comprar a un precio dado.', example: 'La demanda agregada cayó durante el periodo de incertidumbre.' },
    'Demanda Elástica': { definition: 'Situación donde el cambio en el precio afecta significativamente a la cantidad demandada.', example: 'Los productos de lujo suelen tener una demanda elástica.' },
    'Demanda Inelástica': { definition: 'Situación donde la cantidad demandada varía poco ante cambios en el precio.', example: 'La insulina tiene una demanda inelástica porque es necesaria para vivir.' },
    'Denominación de Origen': { definition: 'Sello que garantiza la calidad y procedencia de un producto.', example: 'El vino tiene denominación de origen de la Rioja.' },
    'Depósito a Plazo': { definition: 'Dinero entregado a un banco por un tiempo fijo a cambio de un interés.', example: 'Invertí mis ahorros en un depósito a plazo de un año.' },
    'Depreciación Acelerada': { definition: 'Método contable para amortizar un activo más rápido en sus primeros años.', example: 'La depreciación acelerada permite reducir impuestos al principio de la inversión.' },
    'Depresión Económica': { definition: 'Recesión económica muy prolongada y profunda.', example: 'La Gran Depresión de los años 30 cambió la política económica mundial.' },
    'Derecho de Retención': { definition: 'Facultad de conservar un bien ajeno hasta que se pague una deuda relacionada.', example: 'El taller tiene derecho de retención sobre el coche hasta que se pague la reparación.' },
    'Desahucio': { definition: 'Expulsión de un inquilino de un inmueble por orden judicial.', example: 'El desahucio se produjo tras varios meses de impago del alquiler.' },
    'Desalojo': { definition: 'Acción de obligar a alguien a abandonar un lugar.', example: 'El desalojo de las naves industriales fue necesario para la remodelación.' },
    'Desarrollo Sostenible': { definition: 'Crecimiento que satisface las necesidades actuales sin comprometer a las futuras generaciones.', example: 'El desarrollo sostenible busca equilibrar economía, sociedad y medio ambiente.' },
    'Descapitalización': { definition: 'Pérdida de capital o activos por parte de una empresa.', example: 'La falta de reinversión llevó a la descapitalización de la fábrica.' },
    'Descontar': { definition: 'Reducir el valor futuro de un capital para conocer su valor actual, o aplicar un descuento.', example: 'Para evaluar la inversión, debemos descontar los flujos de caja futuros.' },
    'Descuento Comercial': { definition: 'Operación bancaria para anticipar el importe de una letra o pagaré.', example: 'La empresa usó el descuento comercial para obtener liquidez inmediata.' },
    'Desempleo Friccional': { definition: 'Paro temporal de personas que están cambiando de empleo.', example: 'El desempleo friccional siempre existe en una economía dinámica.' },
    'Desgravación': { definition: 'Reducción de la carga impositiva concedida por ley.', example: 'La desgravación por donaciones a ONGs es del 25%.' },
    'Desinflación': { definition: 'Reducción de la tasa de inflación, aunque los precios sigan subiendo.', example: 'El país está en desinflación porque los precios suben menos que el año pasado.' },
    'Desinversión': { definition: 'Venta de activos o retirada de capital de un negocio.', example: 'La desinversión en carbón es parte de la política ambiental del fondo.' },
    'Desmonetización': { definition: 'Retirada de una moneda de curso legal.', example: 'La desmonetización de los billetes antiguos fue un reto logístico.' },
    'Despacho de Aduanas': { definition: 'Trámites necesarios para que las mercancías entren o salgan legalmente de un país.', example: 'El despacho de aduanas se retrasó por falta de documentación.' },
    'Despido Procedente': { definition: 'Extinción del contrato de trabajo por causas justificadas legalmente.', example: 'El despido procedente fue confirmado por el juez tras probarse las faltas.' },
    'Destajo': { definition: 'Sistema de pago según la cantidad de obra realizada y no por tiempo.', example: 'Trabajar a destajo incentiva la rapidez pero puede afectar a la calidad.' },
    'Deuda Externa': { definition: 'Total de deudas que un país tiene com acreedores extranjeros.', example: 'La renegociación de la deuda externa es vital para el desarrollo del país.' },
    'Deuda Flotante': { definition: 'Deuda a muy corto plazo que el estado emite para cubrir desfases de tesorería.', example: 'El tesoro emitió letras para saldar la deuda flotante del mes.' },
    'Deuda Pública': { definition: 'Deuda total de las administraciones públicas de un país.', example: 'La deuda pública del país supera el 100% de su PIB.' },
    'Devaluación': { definition: 'Reducción oficial del valor de una moneda frente a monedas extranjeras.', example: 'La devaluación de la moneda hizo que las exportaciones fueran más competitivas.' },
    'Diferencial': { definition: 'Margen de beneficio o diferencia entre dos tipos de interés.', example: 'El diferencial del préstamo es del 1% sobre el Euríbor.' },
    'Dinero Electrónico': { definition: 'Valor monetario almacenado en medios electrónicos que sirve para pagar.', example: 'Uso dinero electrónico para mis compras habituales a través del móvil.' },
    'Dinero Fiduciario': { definition: 'Dinero basado en la confianza de que será aceptado, sin respaldo en oro.', example: 'Todas las economías modernas funcionan com dinero fiduciario.' },
    'Dinero Negro': { definition: 'Dinero que no ha sido declarado a hacienda y procede de actividades ilegales o economía sumergida.', example: 'La lucha contra el dinero negro é uma prioridad de la inspección fiscal.' },
    'Disponibilidad': { definition: 'Fondo o bien del que se puede hacer uso inmediatamente.', example: 'La disponibilidad de caja es suficiente para pagar las nóminas.' },
    'Dividendo a Cuenta': { definition: 'Parte del beneficio que se entrega a los accionistas antes del cierre del ejercicio.', example: 'La eléctrica pagará un dividendo a cuenta de 0,10 euros en octubre.' },
    'Dólar': { definition: 'Moneda oficial de Estados Unidos y otros países.', example: 'El dólar se mantuvo estable frente a las principales divisas.' },
    'Domiciliación': { definition: 'Orden al banco para que pague recibos periódicos automáticamente.', example: 'Tengo la domiciliación de todos los suministros en mi cuenta principal.' },
    'Donación': { definition: 'Entrega gratuita de un bien o dinero a favor de otra persona o entidad.', example: 'Hizo una gran donación al museo para ampliar la colección.' },
    'Dow Jones': { definition: 'Índice bursátil que refleja el comportamiento de las 30 mayores empresas cotizadas en EE.UU.', example: 'El Dow Jones cerró com pérdidas tras los datos de empleo.' },
    'Dumping': { definition: 'Práctica de vender productos por debajo de su coste para eliminar competencia.', example: 'El dumping de acero chino fue denunciado ante la Organización Mundial del Comercio.' },

    // E
    'Economía de Mercado': { definition: 'Sistema donde los precios y la producción se determinan por la oferta y la demanda.', example: 'En una economía de mercado, las empresas compiten libremente.' },
    'Especulación': { definition: 'Compra de activos com la esperanza de venderlos más caros a corto plazo.', example: 'La especulación inmobiliaria hizo subir los precios rápidamente.' },
    'Estanflación': { definition: 'Situación económica de estancamiento com alta inflación.', example: 'La estanflación es difícil de combatir porque las medidas habituales pueden empeorar uno de los problemas.' },
    'Euro': { definition: 'Moneda oficial de la Eurozona.', example: 'Necesitas cambiar dólares a euros para viajar a España.' },
    'Excedente': { definition: 'Cantidad en la que los ingresos superan a los gastos (superávit) o la oferta supera a la demanda.', example: 'Tuvimos un excedente de producción de trigo este año.' },
    'Exportación': { definition: 'Venta de bienes o servicios a un país extranjero.', example: 'La exportación de vino es clave para la economía de esa región.' },
    'E-commerce': { definition: 'Comercio electrónico; compra y venta de productos o servicios a través de Internet.', example: 'El e-commerce ha transformado los hábitos de consumo globales.' },
    'Economía Circular': { definition: 'Modelo de producción y consumo que implica compartir, alquilar, reutilizar, reparar, renovar y reciclar materiales existentes.', example: 'La economía circular busca reducir los residuos al mínimo.' },
    'Economía Colaborativa': { definition: 'Sistema en el que se comparten bienes y servicios entre particulares a través de plataformas digitales.', example: 'Airbnb y Uber são ejemplos destacados de economía colaborativa.' },
    'Economía de Escala': { definition: 'Ventaja que obtiene una empresa al aumentar su nivel de producción, lo que reduce el coste por unidad.', example: 'La gran fábrica tiene mayor economía de escala que el pequeño taller.' },
    'Economía Digital': { definition: 'Actividad económica que resulta de las conexiones en línea entre personas, empresas y dispositivos.', example: 'La economía digital representa una parte cada vez mayor del PIB mundial.' },
    'Economía Sumergida': { definition: 'Actividad económica que se mantiene oculta al estado para evitar impuestos o regulaciones.', example: 'La economía sumergida perjudica la recaudación fiscal y los servicios públicos.' },
    'Econometría': { definition: 'Rama de la economía que utiliza métodos estadísticos y matemáticos para analizar datos económicos.', example: 'La econometría permitió predecir el impacto de la subida de tipos.' },
    'Efectivo': { definition: 'Dinero en monedas o billetes de curso legal.', example: 'Solo aceptan pagos en efectivo en este mercado tradicional.' },
    'Efecto de Red': { definition: 'Fenómeno por el cual un producto o servicio gana valor a medida que más personas lo utilizan.', example: 'WhatsApp es muy valioso debido al efecto de red: todos tus contactos están allí.' },
    'Efecto Expulsión': { definition: 'Situación en la que la deuda pública elevada desplaza la inversión privada al subir los tipos de interés.', example: 'El efecto expulsión puede frenar el crecimiento económico a largo plazo.' },
    'Efecto Riqueza': { definition: 'Aumento del consumo de las personas cuando ven que el valor de sus activos (como casas o acciones) aumenta.', example: 'El auge bursátil generó un efecto riqueza que impulsó las ventas minoristas.' },
    'Eficiencia Energética': { definition: 'Uso óptimo de la energía para obtener un resultado determinado com el menor consumo posible.', example: 'La eficiencia energética de los electrodomésticos ayuda a ahorrar en la factura.' },
    'Egreso': { definition: 'Salida de dinero de la contabilidad de una persona o empresa (gasto).', example: 'Debemos controlar los egresos mensuales para no entrar en déficit.' },
    'Ejercicio Fiscal': { definition: 'Periodo de doce meses sobre el que se calculan los impuestos y resultados de una empresa.', example: 'El ejercicio fiscal en España coincide habitualmente com el año natural.' },
    'Elasticidad de la Demanda': { definition: 'Medida de cuánto varía la cantidad demandada de un bien ante cambios en su precio.', example: 'La elasticidad de la demanda de gasolina es baja a corto plazo.' },
    'Elasticidad de la Oferta': { definition: 'Medida del cambio en la cantidad ofrecida ante una variación en el precio del bien.', example: 'La elasticidad de la oferta de productos agrícolas depende del tiempo de cosecha.' },
    'Elasticidad Precio': { definition: 'Mismo que elasticidad de la demanda respecto al precio.', example: 'Calculamos la elasticidad precio para decidir si subimos el coste del servicio.' },
    'Elasticidad Renta': { definition: 'Cambio en la demanda de un bien ante variaciones en el ingreso de los consumidores.', example: 'Los bienes normales tienen una elasticidad renta positiva.' },
    'Emisión de Deuda': { definition: 'Proceso por el cual el estado o una empresa capta fondos del público a cambio de un interés futuro.', example: 'La emisión de deuda pública tuvo una demanda tres veces superior a la oferta.' },
    'Emisor': { definition: 'Entidad que pone en circulación títulos de deuda, acciones o moneda.', example: 'El Tesoro Público es el emisor de los bonos del estado.' },
    'Empleador': { definition: 'Persona o empresa que contrata a trabajadores a cambio de un salario.', example: 'El empleador debe cumplir com todas las normativas de seguridad laboral.' },
    'Empleo': { definition: 'Trabajo realizado a cambio de una remuneración económica.', example: 'El sector servicios es el que genera más empleo en la región.' },
    'Empresa Familiar': { definition: 'Empresa cuya propiedad y dirección están en manos de una familia.', example: 'La empresa familiar ha pasado ya por tres generaciones.' },
    'Empresa Pública': { definition: 'Empresa cuya propiedad y control pertenecen al estado.', example: 'Renfe é uma empresa pública dedicada al transporte ferroviario.' },
    'Enajenación': { definition: 'Acción de transmitir la propiedad de un bien a otra persona.', example: 'La enajenación de la sede social permitió saldar las deudas.' },
    'Encaje Bancario': { definition: 'Reservas que los bancos comerciales deben mantener depositadas en el Banco Central.', example: 'El aumento del encaje bancario reduce la capacidad de préstamo de los bancos.' },
    'Endeudamiento': { definition: 'Relación entre la deuda total de una entidad y sus recursos propios.', example: 'Un nivel de endeudamiento excesivo puede asfixiar a la empresa.' },
    'Endoso': { definition: 'Firma en el reverso de un documento (cheque, pagaré) para transmitir el derecho de cobro.', example: 'Realicé el endoso del cheque para que mi socio pudiera cobrarlo.' },
    'Energía Renovable': { definition: 'Energía que se obtiene de fuentes naturales inagotables.', example: 'La inversión en energía renovable es clave para la transición ecológica.' },
    'Entidad Financiera': { definition: 'Cualquier institución encargada de la intermediación de dinero (bancos, cajas, cooperativas).', example: 'Esa entidad financiera ofrece créditos muy competitivos para jóvenes.' },
    'Entrada de Capital': { definition: 'Inversión de dinero proveniente del extranjero en el país.', example: 'La entrada de capital extranjero impulsó la bolsa nacional.' },
    'Equilibrio de Mercado': { definition: 'Punto donde la cantidad ofrecida iguala a la cantidad demandada a un precio determinado.', example: 'En el equilibrio de mercado, no hay ni excedente ni escasez de producto.' },
    'Escala': { definition: 'Tamaño o dimensión de una actividad económica.', example: 'Producir a gran escala permite reducir los costes unitarios.' },
    'Escasez': { definition: 'Situación en la que los recursos são insuficientes para satisfacer todas las necesidades.', example: 'La escasez de materias primas hizo subir los precios industriales.' },
    'Escritura Pública': { definition: 'Documento firmado ante notario que da fe legal de un acto (compra, herencia).', example: 'Firmamos la escritura pública de la casa esta mañana.' },
    'Estabilidad de Precios': { definition: 'Situación en la que la inflación es baja y predecible.', example: 'El objetivo principal del BCE es mantener la estabilidad de precios.' },
    'Estado de Bienestar': { definition: 'Modelo social donde el estado garantiza servicios básicos y protección a los ciudadanos.', example: 'El estado de bienestar se financia mediante un sistema de impuestos progresivos.' },
    'Estado Financiero': { definition: 'Informes contables que muestran la salud financiera de una empresa.', example: 'Revisamos los estados financieros antes de decidir la inversión.' },
    'Estafa': { definition: 'Delito consistente en engañar a alguien para obtener un beneficio económico.', example: 'Varios inversores fueron víctimas de una estafa piramidal.' },
    'Estándar de Vida': { definition: 'Nivel de bienestar material y comodidad de una persona o población.', example: 'El estándar de vida en la ciudad ha mejorado gracias al nuevo centro logístico.' },
    'Estatutos': { definition: 'Reglas internas que rigen el funcionamiento de una sociedad o asociación.', example: 'Los estatutos de la empresa definen cómo se reparten los beneficios.' },
    'Estímulo Económico': { definition: 'Medidas del gobierno para impulsar la actividad y el consumo.', example: 'El plan de estímulo económico incluyó ayudas directas a familias.' },
    'Estrategia Comercial': { definition: 'Plan para alcanzar objetivos de venta y posicionamiento en el mercado.', example: 'Nuestra estrategia comercial se centra en la calidad y el servicio al cliente.' },
    'Estructura de Costes': { definition: 'Repartición de los gastos fijos y variables de un negocio.', example: 'Analizamos la estructura de costes para identificar posibles ahorros.' },
    'Euríbor': { definition: 'Tipo de interés al que los bancos se prestan dinero entre sí en Europa.', example: 'La mayoría de las hipotecas en España están referenciadas al Euríbor.' },
    'Evaluación de Impacto': { definition: 'Estudio para conocer las consecuencias de una medida o proyecto.', example: 'La evaluación de impacto ambiental es obligatoria para la nueva mina.' },
    'Evasión Fiscal': { definition: 'Acción ilegal de ocultar ingresos o distorsionar información para pagar menos impuestos.', example: 'La evasión fiscal supone una pérdida millonaria para las arcas públicas.' },
    'Exención': { definition: 'Liberación de una obligación o del pago de un impuesto concedida por ley.', example: 'Existe una exención de impuestos para las rentas más bajas.' },
    'Exigible': { definition: 'Deuda o compromiso que debe ser pagado obligatoriamente.', example: 'El pago de la factura será exigible a partir del próximo lunes.' },
    'Existencias': { definition: 'Stock de mercancías o materias primas que una empresa tiene en sus almacenes.', example: 'Debemos reducir existencias antes de que llegue la nueva temporada.' },
    'Expatriado': { definition: 'Persona que reside y trabaja en un país distinto al de su origen por motivos laborales.', example: 'La empresa ofrece un paquete de beneficios muy atractivo para los expatriados.' },
    'Expropiación': { definition: 'Acción del estado de privar a alguien de su propiedad por causa de utilidad pública.', example: 'La expropiación de los terrenos fue necesaria para ampliar la carretera.' },
    'Externalidad Negativa': { definition: 'Efecto perjudicial de una actividad económica sobre terceros que no participan en ella.', example: 'La contaminación de la fábrica é uma externalidad negativa para el pueblo vecino.' },
    'Externalización': { definition: 'Outsourcing; contratar servicios externos para realizar tareas que antes se hacían internamente.', example: 'La externalización de la limpieza permitió a la empresa centrarse en su negocio principal.' },

    // F
    'Fianza': { definition: 'Garantía, generalmente dinero, que asegura el cumplimiento de una obligación.', example: 'El casero pidió un mes de fianza para alquilar el piso.' },
    'Fideicomiso': { definition: 'Contrato por el cual una persona administra bienes en beneficio de otra.', example: 'Creó un fideicomiso para gestionar la herencia de sus hijos.' },
    'Finanzas': { definition: 'Gestión del dinero e inversiones.', example: 'Estudiar finanzas te ayuda a tomar mejores decisiones de inversión.' },
    'Fiscalidad': { definition: 'Conjunto de leyes y normativas relativas a los impuestos.', example: 'Es importante entender la fiscalidad para cumplir com Hacienda.' },
    'Fondo de Inversión': { definition: 'Institución que reúne dinero de muchos inversores para invertirlo en activos.', example: 'Invierto en un fondo indexado al S&P 500.' },
    'Fondo de Cobertura': { definition: 'Fondo de inversión que utiliza estrategias agresivas para obtener altos rendimientos, generalmente para inversores acreditados.', example: 'Los fondos de cobertura a menudo utilizan el apalancamiento para aumentar sus ganancias.' },
    'Fondo Indexado': { definition: 'Fondo de inversión que busca replicar el comportamiento de un índice bursátil.', example: 'Un fondo indexado al Ibex 35 comprará acciones de las 35 mayores empresas de España.' },
    'Fusión': { definition: 'Unión de dos o más empresas para formar una nueva.', example: 'La fusión de los dos bancos creó la entidad más grande del país.' },
    'Facilidades de Crédito': { definition: 'Condiciones favorables que una entidad ofrece para el acceso a préstamos.', example: 'El gobierno anunció nuevas facilidades de crédito para los autónomos.' },
    'Factor de Producción': { definition: 'Recursos necesarios para producir bienes y servicios: tierra, trabajo, capital y tecnología.', example: 'El capital é um factor de producción esencial en la industria pesada.' },
    'Factoraje (Factoring)': { definition: 'Venta de las facturas por cobrar de una empresa a una entidad financiera para obtener liquidez inmediata.', example: 'Usamos el factoraje para cobrar nuestras ventas sin esperar 90 días.' },
    'Factura': { definition: 'Documento que acredita legalmente una operación de compraventa.', example: 'Solicité la factura para poder deducirme el IVA del ordenador.' },
    'Facturación': { definition: 'Suma de los ingresos totales de una empresa por ventas en un periodo.', example: 'Nuestra facturación anual superó los dos millones de euros.' },
    'Familia Económica': { definition: 'Unidad de consumo básico compuesta por personas que comparten presupuesto.', example: 'La familia económica decide cómo repartir sus ingresos entre ahorro y consumo.' },
    'Fiador': { definition: 'Persona que se obliga a pagar por otra si esta no lo hace.', example: 'Actuó como fiador en el contrato de alquiler de su hijo.' },
    'Ficha Técnica': { definition: 'Documento que resume las características y especificaciones de un producto o instrumento financiero.', example: 'Leí la ficha técnica del fondo de inversión para conocer su riesgo.' },
    'Fiduciario': { definition: 'Persona o entidad que administra bienes en beneficio de otra basándose en la confianza.', example: 'El banco actúa como fiduciario del fondo de pensiones de los empleados.' },
    'Filial': { definition: 'Empresa controlada por otra empresa mayor (matriz).', example: 'La multinacional tiene una filial en cada país donde opera.' },
    'Financiación': { definition: 'Obtención de los recursos financieros necesarios para realizar una actividad o compra.', example: 'Estamos buscando financiación bancaria para reformar el local.' },
    'Finanzas Públicas': { definition: 'Estudio de la actividad económica del sector público, ingresos y gastos del estado.', example: 'Las finanzas públicas se ven afectadas por la caída de la recaudación fiscal.' },
    'Fintech': { definition: 'Empresas que utilizan la tecnología más avanzada para ofrecer servicios financieros innovadores.', example: 'Las fintech han revolucionado los pagos móviles y la inversión online.' },
    'Firma Digital': { definition: 'Mecanismo legal para acreditar la identidad del firmante en documentos electrónicos.', example: 'Firmé el contrato de préstamo com mi firma digital desde casa.' },
    'Fiscal': { definition: 'Relativo a los impuestos o a la hacienda pública.', example: 'El año fiscal termina en diciembre para la mayoría de las empresas.' },
    'Fisco': { definition: 'Hacienda pública; conjunto de organismos del estado encargados de los impuestos.', example: 'El fisco endureció los controles sobre las cuentas en el extranjero.' },
    'Flexibilidad Laboral': { definition: 'Capacidad de adaptar el trabajo y las condiciones laborales a las necesidades del mercado o del empleado.', example: 'La flexibilidad laboral permite conciliar mejor la vida personal y profesional.' },
    'Float': { definition: 'Dinero en tránsito entre el momento del pago y el cobro efectivo.', example: 'El float bancario permite a las entidades rentabilizar fondos temporalmente.' },
    'Fletamento': { definition: 'Contrato de alquiler de un vehículo de transporte (barco, avión) para llevar mercancía.', example: 'El fletamento de un carguero para la exportación de grano fue acordado ayer.' },
    'Flujo Monetario': { definition: 'Movimiento de dinero entre los diferentes agentes económicos.', example: 'El flujo monetario se intensifica durante los periodos de expansión económica.' },
    'Fondo de Comercio': { definition: 'Valor inmaterial de una empresa (marca, clientela, reputación) por encima de su valor contable.', example: 'El fondo de comercio de la marca es su activo más valioso.' },
    'Fondo de Pensiones': { definition: 'Patrimonio formado por el ahorro de personas para su jubilación, gestionado por profesionales.', example: 'Su fondo de pensiones invierte una parte en acciones para obtener más rentabilidad.' },
    'Fondo de Reserva': { definition: 'Dinero apartado por una entidad para cubrir posibles pérdidas o gastos futuros imprevistos.', example: 'La comunidad de vecinos tiene un fondo de reserva para reparaciones urgentes.' },
    'Fondos Propios': { definition: 'Parte del pasivo que pertenece a los propietarios de la empresa (capital más beneficios no repartidos).', example: 'La empresa tiene unos fondos propios muy sólidos tras los beneficios de este año.' },
    'Formación Bruta de Capital': { definition: 'Inversión total en activos fijos de un país en un periodo.', example: 'La formación bruta de capital é um indicador clave del crecimiento futuro.' },
    'Fraccionamiento': { definition: 'División del pago de una deuda en varias cuotas periódicas.', example: 'Solicité el fraccionamiento del impuesto para pagarlo en tres meses.' },
    'Franquicia': { definition: 'Modelo de negocio donde una empresa cede el derecho de explotar su marca a un tercero.', example: 'Abrir una franquicia de comida rápida reduce el riesgo inicial del negocio.' },
    'Fraude': { definition: 'Acción contraria a la verdad y a la rectitud para perjudicar a alguien o al estado.', example: 'Fue investigado por fraude en las subvenciones públicas recibidas.' },
    'Free Trade': { definition: 'Libre comercio; ausencia de aranceles y barreras entre países.', example: 'El acuerdo de free trade impulsó las exportaciones zonales.' },
    'Frontera de Posibilidades de Producción': { definition: 'Gráfico que muestra la cantidad máxima de bienes que una economía puede producir com sus recursos.', example: 'La frontera de posibilidades de producción se desplaza con la mejora tecnológica.' },
    'Fuente de Ingresos': { definition: 'Origen del dinero que recibe una persona o entidad.', example: 'Su principal fuente de ingresos es el salario, pero también tiene alquileres.' },
    'Fuerza Mayor': { definition: 'Circunstancia imprevisible e inevitable que impide cumplir una obligación.', example: 'El terremoto fue considerado fuerza mayor para no entregar el pedido a tiempo.' },
    'Fungible': { definition: 'Bien que se consume com el uso y puede ser sustituido por otro de la misma especie (como el dinero).', example: 'El dinero es el bien fungible por excelencia.' },
    'Futuros': { definition: 'Contratos financieros para comprar o vender un activo en una fecha futura a un precio pactado hoy.', example: 'Los agricultores usan contratos de futuros para asegurar el precio de su cosecha.' },

    // G
    'Gasto Público': { definition: 'Dinero que el estado emplea en bienes y servicios públicos.', example: 'El gasto público en educación aumentó este año.' },
    'Garantía': { definition: 'Seguridad que se ofrece para asegurar el pago de una deuda.', example: 'La casa sirvió de garantía para el préstamo hipotecario.' },
    'Ganancia de Capital': { definition: 'Beneficio obtenido por la venta de un activo a un precio superior al de compra.', example: 'Tendrá que pagar impuestos sobre la ganancia de capital de sus acciones.' },
    'Globalización': { definition: 'Proceso de interconexión e interdependencia de las economías mundiales.', example: 'La globalización permite comprar productos de cualquier parte del mundo.' },
    'Gasto Corriente': { definition: 'Dinero que el estado o una empresa dedica al funcionamiento diario (nóminas, suministros).', example: 'El gasto corriente del ayuntamiento aumentó debido a la subida de la luz.' },
    'Gasto de Capital': { definition: 'Inversión en activos fijos que aumentan el patrimonio o la capacidad productiva.', example: 'La compra de nuevas furgonetas é um gasto de capital para la empresa de reparto.' },
    'Gastos de Explotación': { definition: 'Costes necesarios para mantener en funcionamiento un negocio o actividad económica.', example: 'Reducir los gastos de explotación es clave para mejorar el margen neto.' },
    'Gastos de Representación': { definition: 'Gastos realizados por directivos o empleados para promocionar la empresa ante clientes.', example: 'La comida com los inversores se cargó como gastos de representación.' },
    'G-20': { definition: 'Foro internacional de los gobernantes y presidentes de bancos centrales de las 20 economías más importantes del mundo.', example: 'El G-20 se reunió para coordinar políticas contra la crisis financiera global.' },
    'Ganancia': { definition: 'Beneficio económico obtenido de una actividad o inversión.', example: 'La ganancia obtenida en la venta de las acciones fue mayor de lo esperado.' },
    'Generación de Riqueza': { definition: 'Proceso de creación de valor y bienestar económico en una sociedad.', example: 'La innovación tecnológica es el principal motor de generación de riqueza hoy en día.' },
    'Gerencia': { definition: 'Cargo o departamento encargado de la gestión y dirección de una empresa.', example: 'La gerencia decidió cambiar el sistema de incentivos para los vendedores.' },
    'Gestor': { definition: 'Persona que administra bienes o intereses ajenos, o tramita asuntos administrativos.', example: 'Mi gestor se encarga de presentar todos los modelos de impuestos trimestrales.' },
    'Giro': { definition: 'Orden de pago enviada de una plaza a otra, generalmente por correo o telégrafo.', example: 'Envié el dinero del alquiler mediante un giro postal.' },
    'Glosario': { definition: 'Catálogo de palabras de una misma disciplina com su definición.', example: 'Este glosario económico ayuda a entender los términos más complejos del mercado.' },
    'Gobernanza': { definition: 'Manera en que se dirige y controla una organización o estado para asegurar su buen funcionamiento.', example: 'La buena gobernanza corporativa es esencial para atraer inversores internacionales.' },
    'Gracia': { definition: 'Periodo de tiempo en el que no se obliga al pago de una deuda o interés (periodo de carencia).', example: 'El préstamo tiene dos años de gracia antes de empezar a amortizar el capital.' },
    'Gran Empresa': { definition: 'Entidad económica com un elevado número de trabajadores y gran facturación.', example: 'Las grandes empresas tienen departamentos de recursos humanos muy especializados.' },
    'Gravamen': { definition: 'Carga impositiva u obligación que pesa sobre un bien o persona.', example: 'El gravamen sobre el tabaco busca reducir su consumo por salud pública.' },
    'Gremio': { definition: 'Asociación de profesionales que ejercen un mismo oficio o profesión.', example: 'El gremio de hostelería protestó por las nuevas restricciones de horario.' },
    'Grupo de Presión': { definition: 'Lobby; colectivo que intenta influir en las decisiones del gobierno a favor de sus intereses.', example: 'El grupo de presión de las renovables impulsó la nueva ley de energía.' },
    'Grupo Económico': { definition: 'Conjunto de empresas que, aunque são jurídicamente independientes, actúan bajo una misma dirección.', example: 'El grupo económico decidió centralizar las compras para ahorrar costes.' },
    'Garantía Hipotecaria': { definition: 'Derecho que se otorga sobre un inmueble para asegurar el pago de un crédito.', example: 'La garantía hipotecaria es lo que permite al banco subastar la casa si no pagas.' },

    // H
    'Haber': { definition: 'Columna derecha en una cuenta contable donde se registran ingresos o aumentos de pasivo.', example: 'Anota ese ingreso en el haber de la cuenta.' },
    'Hipoteca': { definition: 'Préstamo a largo plazo garantizado por un bien inmueble.', example: 'Acabo de firmar una hipoteca a 25 años para mi piso.' },
    'Hiperinflación': { definition: 'Inflación extremadamente alta y fuera de control.', example: 'Venezuela sufrió hiperinflación, donde los precios cambiaban cada día.' },
    'Holding': { definition: 'Sociedad que posee la mayoría de las acciones y el control de otras compañías.', example: 'Inditex es el holding que controla marcas como Zara y Massimo Dutti.' },
    'Hacienda Pública': { definition: 'Conjunto de organismos del estado encargados de la gestión de los recursos públicos e impuestos.', example: 'Hacienda Pública investiga el origen de los fondos no declarados.' },
    'Hachazo Fiscal': { definition: 'Expresión coloquial para referirse a una subida fuerte e inesperada de impuestos.', example: 'Los autónomos temen un hachazo fiscal en la próxima reforma.' },
    'Hard Currency': { definition: 'Moneda fuerte; divisa que es estable y ampliamente aceptada en el mundo.', example: 'El franco suizo es considerado una hard currency por excelencia.' },
    'Hecho Imponible': { definition: 'Circunstancia cuya realización genera la obligación de pagar un impuesto.', example: 'La compra de un coche es el hecho imponible del impuesto de transmisiones.' },
    'Herencia': { definition: 'Conjunto de bienes y deudas que se transmiten a los herederos tras el fallecimiento de una persona.', example: 'La gestión de la herencia se complicó por la falta de un testamento claro.' },
    'Hidrocarburos': { definition: 'Compuestos orgánicos (petróleo, gas) que são base de la energía industrial.', example: 'El precio de los hidrocarburos influye directamente en el coste del transporte.' },
    'Hipermercado': { definition: 'Establecimiento comercial de gran superficie que vende productos de alimentación y hogar.', example: 'El nuevo hipermercado creó quinientos puestos de trabajo en la periferia.' },
    'Hipoteca Inversa': { definition: 'Préstamo para mayores de 65 años garantizado por su vivienda, que no se devuelve hasta el fallecimiento.', example: 'La hipoteca inversa permite a los jubilados complementar su pensión.' },
    'Hogar': { definition: 'Unidad económica formada por una persona o grupo que comparten gastos de vivienda.', example: 'El presupuesto medio por hogar ha caído debido a la inflación.' },
    'Holding Company': { definition: 'Empresa madre que controla a otras a través de la propiedad de sus acciones.', example: 'La holding company centraliza la dirección estratégica del grupo.' },
    'Homologación': { definition: 'Aceptación oficial de que un producto cumple com las normas de calidad o seguridad requeridas.', example: 'La homologación del nuevo modelo de coche tardó varios meses.' },
    'Honorarios': { definition: 'Retribución que recibe un profesional liberal (abogado, médico) por sus servicios.', example: 'Los honorarios del arquitecto se fijaron como un porcentaje del presupuesto.' },

    // I
    'Importación': { definition: 'Compra de bienes o servicios provenientes de otro país.', example: 'La importación de petróleo es vital para países sin reservas energéticas.' },
    'Impuesto': { definition: 'Tributo que los ciudadanos pagan al estado para financiar el gasto público.', example: 'El IVA é um impuesto al consumo.' },
    'Índice de Precios': { definition: 'Medida estadística de la evolución de los precios (como el IPC).', example: 'El índice de precios subió un 3% este mes.' },
    'Inflación': { definition: 'Aumento generalizado y sostenido de los precios de bienes y servicios.', example: 'La inflación hace que tu dinero compre menos cosas com el tiempo.' },
    'Ingreso': { definition: 'Entrada de dinero que recibe una persona o empresa.', example: 'Sus ingresos provienen principalmente de su salario y alquileres.' },
    'Insolvencia': { definition: 'Incapacidad para pagar las deudas cuando vencen.', example: 'La empresa se declaró en insolvencia al no poder pagar a sus proveedores.' },
    'Interés': { definition: 'Precio que se paga por el uso del dinero ajeno, o rendimiento de una inversión.', example: 'El banco me cobra un 5% de interés por el préstamo.' },
    'Inversión': { definition: 'Uso de capital com el objetivo de obtener un beneficio futuro.', example: 'Comprar acciones é uma inversión a largo plazo.' },
    'I+D+i': { definition: 'Investigación, Desarrollo e Innovación tecnológica.', example: 'Las empresas que más invierten en I+D+i suelen ser las más competitivas.' },
    'IAE': { definition: 'Impuesto sobre Actividades Económicas; tributo que grava el ejercicio de actividades empresariales.', example: 'El alta en el IAE es obligatoria antes de empezar cualquier negocio.' },
    'IBAN': { definition: 'Código internacional para identificar cuentas bancarias de forma única.', example: 'Necesito tu código IBAN para hacerte la transferencia del pago.' },
    'Ibex 35': { definition: 'Índice bursátil de referencia de la bolsa española com las 35 empresas más líquidas.', example: 'El Ibex 35 subió hoy impulsado por los buenos resultados de la banca.' },
    'IBI': { definition: 'Impuesto sobre Bienes Inmuebles; tributo municipal que grava la propiedad de terrenos y edificios.', example: 'El recibo del IBI se paga anualmente al ayuntamiento de la ciudad.' },
    'Imposición': { definition: 'Acción de imponer un tributo o depósito de dinero en una entidad.', example: 'La imposición a plazo fijo é uma forma segura de ahorrar.' },
    'Impuesto de Sociedades': { definition: 'Impuesto directo que grava el beneficio neto de las empresas y personas jurídicas.', example: 'El impuesto de sociedades se liquida anualmente mediante el modelo 200.' },
    'Impuesto Directo': { definition: 'Tributo que se aplica sobre la renta o el patrimonio de las personas de forma directa.', example: 'El IRPF es el impuesto directo más importante para los ciudadanos.' },
    'Impuesto Indirecto': { definition: 'Tributo que se aplica sobre el consumo de bienes y servicios (como el IVA).', example: 'Los impuestos indirectos afectan por igual a todos los consumidores, sin importar su renta.' },
    'Impuesto sobre el Patrimonio': { definition: 'Tributo que grava la riqueza neta de las personas físicas.', example: 'El impuesto sobre el patrimonio ha sido objeto de debate político en diversas regiones.' },
    'Impuesto sobre la Renta (IRPF)': { definition: 'Impuesto progresivo sobre los ingresos de las personas residentes en España.', example: 'La declaración del IRPF debe presentarse entre abril y junio de cada año.' },
    'Impuesto sobre Transmisiones': { definition: 'Tributo que grava la compraventa de bienes de segunda mano entre particulares.', example: 'Al comprar el coche usado tuve que pagar el impuesto sobre transmisiones patrimoniales.' },
    'Impugnación': { definition: 'Acción legal para oponerse a una decisión, contrato o liquidación de impuestos.', example: 'Presentamos una impugnación contra la sanción de hacienda por falta de pruebas.' },
    'Imputación': { definition: 'Asignación de un coste, ingreso o renta a una persona o departamento determinado.', example: 'La imputación de rentas inmobiliarias se aplica a las segundas viviendas vacías.' },
    'Incumplimiento': { definition: 'Falta de realización de una obligación acordada en un contrato o ley.', example: 'El incumplimiento de las condiciones del préstamo puede llevar al embargo.' },
    'Indemnización': { definition: 'Compensación económica por un daño, perjuicio o despido laboral.', example: 'Recibió una indemnización de veinte días por año tras su despido por causas objetivas.' },
    'Indexación': { definition: 'Ajuste de un valor o precio en función de la variación de un índice (como el IPC).', example: 'La indexación de las pensiones asegura que no pierdan poder adquisitivo.' },
    'Indicador Adelantado': { definition: 'Variable económica que cambia antes que la economía en su conjunto, permitiendo predecir tendencias.', example: 'La confianza de los empresarios é um indicador adelantado de la inversión futura.' },
    'Indicador Económico': { definition: 'Dato estadístico que permite analizar la situación de la economía de un país.', example: 'La tasa de paro es el indicador económico que más preocupa a la sociedad.' },
    'Inditex': { definition: 'Empresa multinacional española, líder mundial en fabricación y distribución textil.', example: 'Inditex es la empresa com mayor peso en el selectivo español Ibex 35.' },
    'Industria': { definition: 'Sector económico dedicado a la transformación de materias primas en productos elaborados.', example: 'La industria automotriz ha sufrido cambios profundos por la electrificación.' },
    'Ineficiencia': { definition: 'Uso inadecuado de los recursos que impide alcanzar el máximo resultado posible.', example: 'La ineficiencia del sistema de transporte genera costes adicionales a las empresas.' },
    'Inflación Subyacente': { definition: 'Índice de inflación que excluye los precios de energía y alimentos no elaborados por ser volátiles.', example: 'El Banco Central mira la inflación subyacente para ver la tendencia de precios a largo plazo.' },
    'Informe Anual': { definition: 'Documento que publican las empresas para informar de su actividad y estados financieros del año.', example: 'Leí el informe anual de la tecnológica para entender su estrategia de futuro.' },
    'Infraestructura': { definition: 'Conjunto de elementos o servicios necesarios para el funcionamiento de una economía (carreteras, redes eléctricas).', example: 'La mejora de la infraestructura ferroviaria impulsó el comercio regional.' },
    'Ingreso Bruto': { definition: 'Total de dinero recibido antes de aplicar impuestos y deducciones.', example: 'Mi ingreso bruto anual es de treinta mil euros.' },
    'Ingreso Disponible': { definition: 'Parte de la renta que queda libre para consumir o ahorrar tras pagar impuestos.', example: 'La subida del IRPF redujo el ingreso disponible de las familias.' },
    'Ingreso Marginal': { definition: 'Variación que experimenta el ingreso total al vender una unidad adicional de producto.', example: 'La empresa dejará de producir cuando el ingreso marginal sea igual al coste marginal.' },
    'Ingreso Neto': { definition: 'Cantidad de dinero que efectivamente se recibe tras todos los descuentos legales.', example: 'Mi ingreso neto mensual es lo que realmente puedo gastar.' },
    'Ingreso Per Cápita': { definition: 'Promedio de ingresos por cada habitante de un país.', example: 'El ingreso per cápita é uma medida común del nivel de desarrollo económico.' },
    'Inmueble': { definition: 'Bien que no puede transportarse, como un terreno, casa o edificio.', example: 'La inversión en inmuebles es tradicionalmente vista como segura en España.' },
    'Innovación': { definition: 'Aplicación de nuevas ideas, procesos o productos que aportan valor añadido.', example: 'La innovación constante es necesaria para sobrevivir en mercados competitivos.' },
    'Insumo': { definition: 'Cualquier recurso o factor productivo que se utiliza para crear un bien o servicio.', example: 'El petróleo es el principal insumo de la industria plástica.' },
    'Institución Financiera': { definition: 'Organización que actúa como intermediaria en los mercados financieros.', example: 'Las instituciones financieras fueron rescatadas durante la gran recesión.' },
    'Instrumento Financiero': { definition: 'Contrato que genera un activo para una parte y un pasivo para la otra (acciones, bonos).', example: 'El derivado é um instrumento financiero cuyo valor depende de otro activo.' },
    'Intangible': { definition: 'Bien que no tiene presencia física (marca, patente, software) pero tiene valor económico.', example: 'La patente del nuevo medicamento es el mayor activo intangible del laboratorio.' },
    'Interés Compuesto': { definition: 'Interés que se calcula sobre el capital inicial y también sobre los intereses acumulados de periodos anteriores.', example: 'El interés compuesto permite que los ahorros crezcan de forma exponencial com el tiempo.' },
    'Interés de Demora': { definition: 'Recargo que se paga por el retraso en el cumplimiento de una obligación de pago.', example: 'Tuve que pagar un 4% de interés de demora por pagar el recibo fuera de plazo.' },
    'Interés Fijo': { definition: 'Tasa de interés que no varía durante toda la vida del préstamo o depósito.', example: 'Prefiero una hipoteca a interés fijo para saber siempre cuánto pagaré.' },
    'Interés Nominal': { definition: 'Tipo de interés que se pacta en la operación sin tener en cuenta la inflación o gastos.', example: 'El interés nominal del préstamo es del 6% semestral.' },
    'Interés Real': { definition: 'Tipo de interés ajustado por la inflación, que muestra el poder adquisitivo real.', example: 'Si el interés es del 5% y la inflación del 3%, el interés real es solo del 2%.' },
    'Interés Variable': { definition: 'Tasa de interés que cambia periódicamente en función de un índice de referencia (como el Euríbor).', example: 'Las cuotas de mi préstamo subieron al subir el Euríbor, ya que es a interés variable.' },
    'Intermediación': { definition: 'Actividad de poner en contacto a oferentes y demandantes de fondos en los mercados.', example: 'Los bancos ganan dinero mediante la intermediación financiera.' },
    'Intervencionismo': { definition: 'Política económica basada en la participación activa del estado en los mercados.', example: 'El intervencionismo excesivo puede desincentivar la inversión privada.' },
    'Inventario': { definition: 'Registro detallado y valorado de todos los bienes de una empresa en un momento dado.', example: 'Hacemos inventario en la tienda cada seis meses para detectar faltas.' },
    'Inversión de Impacto': { definition: 'Inversión realizada com la intención de generar un impacto social o ambiental positivo junto con un retorno financiero.', example: 'La inversión de impacto ayuda a financiar proyectos de agua potable en países pobres.' },
    'Inversión Directa': { definition: 'Inversión que busca tener una participación duradera y de control en una empresa.', example: 'La inversión directa extranjera es fundamental para crear fábricas y empleo.' },
    'Inversión Extranjera': { definition: 'Capital que fluye de un país a otro para ser invertido en activos o empresas.', example: 'El país ofrece incentivos para atraer inversión extranjera en el sector turístico.' },
    'Inversionista': { definition: 'Inversor; persona o entidad que dedica su capital a comprar activos para obtener beneficio.', example: 'El inversionista analizó los riesgos antes de comprar acciones de la startup.' },
    'Inyección de Liquidez': { definition: 'Acción del Banco Central de poner más dinero en circulación en el sistema bancario.', example: 'La inyección de liquidez evitó el colapso del sistema de pagos durante la crisis.' },
    'IPC': { definition: 'Índice de Precios al Consumo; indicador que mide el coste de la vida.', example: 'El IPC subió un 4% este año debido al precio de la energía.' },
    'IRNR': { definition: 'Impuesto sobre la Renta de No Residentes; tributo para personas que obtienen rentas en España sin vivir en ella.', example: 'Si vendes tu casa de vacaciones en España siendo extranjero, debes pagar el IRNR.' },
    'ISIN': { definition: 'Código internacional de identificación de valores mobiliarios (acciones, bonos).', example: 'Facilítame el código ISIN del fondo para poder buscarlo en la plataforma.' },
    'IVA': { definition: 'Impuesto sobre el Valor Añadido; impuesto indirecto sobre el consumo.', example: 'El tipo general del IVA en España es del 21%.' },

    // J
    'Jubilación': { definition: 'Cese de la actividad laboral por edad o incapacidad, y la pensión que se recibe.', example: 'Está ahorrando para tener una jubilación cómoda.' },
    'Junta General': { definition: 'Reunión de los accionistas de una empresa para tomar decisiones importantes.', example: 'La Junta General aprobó las cuentas anuales.' },
    'Jornada Laboral': { definition: 'Tiempo que cada trabajador dedica diariamente a su trabajo.', example: 'La jornada laboral estándar en España es de 40 horas semanales.' },
    'Justiprecio': { definition: 'Indemnización justa que se paga por la expropiación de un bien por utilidad pública.', example: 'El propietario recurrió el justiprecio al considerarlo inferior al valor de mercado.' },
    'Juez de lo Mercantil': { definition: 'Magistrado especializado en juzgar asuntos relacionados com empresas y sociedades.', example: 'El juez de lo mercantil preside el concurso de acreedores de la aerolínea.' },
    'Juicio Universal': { definition: 'Procedimiento judicial que afecta a la totalidad del patrimonio de una persona (como la quiebra o herencia).', example: 'El concurso de acreedores é um juicio universal donde se llaman a todos los acreedores.' },
    'Jurisdicción': { definition: 'Poder de un juez o autoridad para juzgar y hacer ejecutar lo juzgado en un territorio o materia.', example: 'Este tribunal no tiene jurisdicción sobre empresas extranjeras sin sede en España.' },
    'Justificante': { definition: 'Documento que sirve para probar un gasto, pago o realización de una actividad.', example: 'Necesito el justificante bancario de la transferencia para acreditar el pago.' },

    // K
    'Know-how': { definition: 'Conjunto de conocimientos técnicos y habilidades prácticas de una empresa.', example: 'El know-how de sus ingenieros es la ventaja competitiva de la empresa.' },
    'Kanban': { definition: 'Sistema visual de gestión de proyectos que permite ver el estado del flujo de trabajo.', example: 'Usamos un tablero Kanban para organizar las tareas del equipo de desarrollo.' },
    'Keynesianismo': { definition: 'Teoría económica que propone la intervención del estado para estimular la demanda y el empleo.', example: 'El keynesianismo fue la base de las políticas económicas tras la Segunda Guerra Mundial.' },
    'Kilo': { definition: 'Prefijo que indica mil (usado en economía como K para referirse a miles de euros o dólares).', example: 'La inversión inicial fue de 50K euros.' },
    'Kondratieff': { definition: 'Ciclos económicos de largo plazo (40-60 años) caracterizados por fases de auge y depresión.', example: 'La teoría de Kondratieff vincula los ciclos largos com las grandes innovaciones tecnológicas.' },

    // L
    'Largo Plazo': { definition: 'Periodo de tiempo extendido, generalmente superior a un año.', example: 'Invertir en bolsa suele ser más rentable a largo plazo.' },
    'Leasing': { definition: 'Contrato de alquiler com opción a compra al final del periodo.', example: 'La empresa adquirió la maquinaria mediante un leasing.' },
    'Liquidez': { definition: 'Facilidad com la que un activo puede convertirse en dinero efectivo.', example: 'El dinero en cuenta corriente tiene alta liquidez.' },
    'Lucro': { definition: 'Ganancia o beneficio que se obtiene de una cosa.', example: 'Es una organización sin ánimo de lucro.' },
    'Letra de Cambio': { definition: 'Documento mercantil por el cual una persona ordena a otra el pago de una cantidad de dinero en una fecha.', example: 'El proveedor exigió una letra de cambio aceptada como garantía de pago.' },
    'Letra del Tesoro': { definition: 'Título de deuda pública a corto plazo emitida por el estado para financiarse.', example: 'Las letras del tesoro a doce meses tienen ahora una rentabilidad muy atractiva.' },
    'Ley de la Oferta y la Demanda': { definition: 'Principio económico que explica la relación entre la cantidad de un bien y su precio en el mercado.', example: 'La ley de la oferta y la demanda determinó la subida del precio del aceite.' },
    'Ley de Say': { definition: 'Teoría económica que afirma que la oferta crea su propia demanda.', example: 'La ley de Say es uno de los pilares de la economía clásica.' },
    'Liberalismo': { definition: 'Doctrina económica que defiende la mínima intervención del estado y la máxima libertad individual.', example: 'El liberalismo económico aboga por la reducción de aranceles y regulaciones.' },
    'Liberación': { definition: 'Proceso de eliminar restricciones legales o controles sobre una actividad económica.', example: 'La liberación del sector eléctrico aumentó la competencia entre empresas.' },
    'Libor': { definition: 'Tipo de interés al que los bancos de Londres se prestan dinero (equivalente británico al Euríbor).', example: 'Muchos contratos financieros internacionales están referenciados al Libor.' },
    'Libre Comercio': { definition: 'Sistema comercial donde no existen aranceles ni barreras entre los países que intercambian bienes.', example: 'El tratado de libre comercio facilitó las exportaciones hacia el mercado americano.' },
    'Libre Mercado': { definition: 'Sistema donde los precios se determinan exclusivamente por la interacción de compradores y vendedores.', example: 'En un libre mercado perfecto, el estado no interviene en la fijación de precios.' },
    'Licitación': { definition: 'Proceso de concurso público para adjudicar la realización de una obra o servicio.', example: 'La empresa constructora presentó su oferta para la licitación del nuevo puente.' },
    'Licitador': { definition: 'Persona o empresa que participa en una licitación pública.', example: 'Hubo diez licitadores compitiendo por el contrato de limpieza urbana.' },
    'Liquidación': { definition: 'Proceso de cierre de una empresa, venta de sus activos y pago de deudas, o pago final de un impuesto.', example: 'La liquidación del impuesto de sociedades debe hacerse antes del 25 de julio.' },
    'Lista de Precios': { definition: 'Documento o catálogo donde se detallan los precios de venta de los productos de una empresa.', example: 'Enviamos la nueva lista de precios a todos nuestros clientes mayoristas.' },
    'Lote': { definition: 'Conjunto de bienes que se venden o producen de forma agrupada.', example: 'Compré un lote de acciones de la tecnológica a un precio muy bajo.' },
    'Logística': { definition: 'Conjunto de medios y métodos necesarios para llevar a cabo la organización de una empresa o servicio, especialmente de transporte y distribución.', example: 'La logística de Amazon es envidiada por su rapidez y eficiencia.' },
    'Lucro Cesante': { definition: 'Pérdida de una ganancia legítima que se iba a obtener si no hubiera ocurrido un daño o incumplimiento.', example: 'El seguro cubrió tanto el daño directo como el lucro cesante tras la inundación del local.' },

    // M
    'Macroeconomía': { definition: 'Estudio de la economía en su conjunto (país, región, mundo).', example: 'La macroeconomía analiza el desempleo, la inflación y el crecimiento.' },
    'Margen': { definition: 'Diferencia entre el precio de venta y el costo de producción.', example: 'Tienen un margen de beneficio del 20% en cada producto.' },
    'Mercado': { definition: 'Lugar o mecanismo donde se intercambian bienes y servicios.', example: 'El mercado inmobiliario está muy activo este año.' },
    'Mercado Alcista': { definition: 'Período en el que los precios de los activos suben o se espera que suban.', example: 'En un mercado alcista, los inversores suelen mostrarse optimistas.' },
    'Mercado Bajista': { definition: 'Período en el que los precios de los activos caen, generalmente un 20% o más desde máximos.', example: 'Durante un mercado bajista, muchos inversores prefieren mantener efectivo.' },
    'Microeconomía': { definition: 'Estudio del comportamiento económico de agentes individuales (empresas, hogares).', example: 'La microeconomía analiza cómo decides qué comprar.' },
    'Moneda': { definition: 'Dinero utilizado en un país específico.', example: 'El peso es la moneda de México.' },
    'Monopolio': { definition: 'Situación de mercado donde hay un solo vendedor para un producto.', example: 'La empresa eléctrica tiene un monopolio en la región.' },
    'Manufactura': { definition: 'Proceso de fabricación de un producto a través de medios mecánicos o manuales.', example: 'La manufactura de calzado es la principal industria de esta ciudad.' },
    'Maquila': { definition: 'Sistema de producción donde una empresa importa materias primas sin aranceles para fabricar productos y exportarlos.', example: 'Las maquilas en la frontera generan miles de empleos industriales.' },
    'Marco Económico': { definition: 'Conjunto de condiciones y parámetros que definen la situación y reglas de una economía.', example: 'El nuevo marco económico favorece la inversión extranjera a largo plazo.' },
    'Masa Monetaria': { definition: 'Cantidad total de dinero líquido (efectivo y depósitos) que circula en una economía.', example: 'El Banco Central controla la masa monetaria para mantener la estabilidad de precios.' },
    'Materia Prima': { definition: 'Bien básico que se extrae de la naturaleza para ser transformado en productos elaborados.', example: 'El hierro es la materia prima fundamental para la industria del acero.' },
    'Matriz': { definition: 'Empresa principal que posee y controla a otras empresas llamadas filiales.', example: 'La matriz del grupo decidió vender su división de seguros.' },
    'Máximo': { definition: 'Valor más alto alcanzado por un precio o indicador en un periodo determinado.', example: 'La bolsa de Nueva York alcanzó un nuevo máximo histórico hoy.' },
    'Mayorista': { definition: 'Comerciante que vende productos en grandes cantidades a otros comerciantes o empresas, no al consumidor final.', example: 'Compramos los suministros de oficina a un mayorista para ahorrar costes.' },
    'Mecenazgo': { definition: 'Patrocinio financiero de actividades artísticas, culturales o científicas de forma desinteresada.', example: 'El mecenazgo cultural permite mantener museos y becas de arte.' },
    'Mediador': { definition: 'Persona que interviene entre dos partes para ayudarlas a llegar a un acuerdo comercial o laboral.', example: 'El mediador evitó la huelga al acercar las posturas de la empresa y el sindicato.' },
    'Medio de Cambio': { definition: 'Cualquier objeto que es aceptado ampliamente para el intercambio de bienes y servicios (generalmente el dinero).', example: 'El dinero es el medio de cambio más eficiente inventado por el hombre.' },
    'Medio de Pago': { definition: 'Instrumento que permite saldar una deuda o compra (efectivo, tarjeta, transferencia).', example: 'La tarjeta de débito es mi medio de pago preferido por comodidad.' },
    'Memoria Anual': { definition: 'Documento donde una empresa resume su actividad, logros y estados financieros del año.', example: 'La memoria anual está disponible para todos los accionistas en la web.' },
    'Mercader': { definition: 'Persona que trata o comercia com géneros vendibles.', example: 'Los antiguos mercaderes de la Ruta de la Seda intercambiaban especias y telas.' },
    'Mercadería': { definition: 'Bien com el que se comercia en un negocio.', example: 'Recibimos una nueva remesa de mercadería para la campaña de Navidad.' },
    'Mercancía': { definition: 'Cualquier objeto mueble que es propiedad de una empresa y está destinado a la venta.', example: 'La mercancía se transporta en contenedores por vía marítima.' },
    'Mercantil': { definition: 'Relativo al comercio o a los comerciantes.', example: 'El código mercantil regula las relaciones legales entre las empresas.' },
    'Mercado Común': { definition: 'Acuerdo entre países para permitir el libre movimiento de bienes, servicios, capitales y personas.', example: 'El mercado común europeo ha impulsado el crecimiento de todos sus miembros.' },
    'Mercado de Capitales': { definition: 'Mercado financiero donde se negocian activos a largo plazo (acciones y bonos).', example: 'Las empresas acuden al mercado de capitales para financiarse.' },
    'Mercado de Divisas': { definition: 'Forex; mercado global donde se intercambian las monedas de los diferentes países.', example: 'El mercado de divisas es el más líquido y activo del mundo.' },
    'Mercado de Valores': { definition: 'Sistema donde se negocian títulos valores (principalmente la bolsa).', example: 'La volatilidad del mercado de valores aumentó tras los datos de inflación.' },
    'Mercado de Trabajo': { definition: 'Espacio donde confluyen la oferta de trabajadores y la demanda de las empresas.', example: 'El mercado de trabajo necesita perfiles más tecnológicos y adaptables.' },
    'Mercado Emergente': { definition: 'Economía com potencial de crecimiento rápido que está en proceso de industrialización.', example: 'Brasil e India são considerados mercados emergentes muy atractivos para invertir.' },
    'Mercado Financiero': { definition: 'Lugar o mecanismo donde se intercambian activos financieros y se fijan sus precios.', example: 'La estabilidad del mercado financiero es clave para la confianza económica.' },
    'Mercado Inmobiliario': { definition: 'Sector dedicado a la compra, venta y alquiler de bienes inmuebles.', example: 'El mercado inmobiliario en las grandes ciudades sigue mostrando precios elevados.' },
    'Mercado Laboral': { definition: 'Mismo que mercado de trabajo; relación entre empleadores y empleados.', example: 'La reforma del mercado laboral busca reducir la temporalidad de los contratos.' },
    'Mercado Mayorista': { definition: 'Mercado donde se negocian grandes volúmenes de productos a precios inferiores a los de consumo.', example: 'El precio de la electricidad se fija diariamente en el mercado mayorista.' },
    'Mercado Minorista': { definition: 'Mercado donde se venden productos directamente al consumidor final al por menor.', example: 'El mercado minorista se enfrenta a la competencia del comercio electrónico.' },
    'Mercado Monetario': { definition: 'Mercado financiero donde se negocian activos com alta liquidez y vencimiento a corto plazo.', example: 'El mercado monetario se utiliza para gestionar la liquidez diaria de los bancos.' },
    'Mercado Primario': { definition: 'Mercado donde se emiten y venden por primera vez nuevos títulos valores.', example: 'La empresa captó fondos en el mercado primario mediante una ampliación de capital.' },
    'Mercado Secundario': { definition: 'Mercado donde se compran y venden activos que ya fueron emitidos previamente (como la bolsa).', example: 'La mayoría de las operaciones bursátiles diarias ocurren en el mercado secundario.' },
    'Mercadotecnia': { definition: 'Marketing; conjunto de técnicas para mejorar la comercialización de un producto.', example: 'La mercadotecnia digital es esencial para llegar al público joven.' },
    'Mercosur': { definition: 'Mercado Común del Sur; proceso de integración económica entre varios países de América del Sur.', example: 'El Mercosur busca eliminar las barreras comerciales entre Argentina, Brasil, Paraguay y Uruguay.' },
    'Merma': { definition: 'Pérdida de valor o cantidad de un producto por causas naturales o de manipulación.', example: 'El transporte de fruta siempre conlleva una merma del 5%.' },
    'Método de Valoración': { definition: 'Técnica utilizada para determinar el valor económico de un activo o empresa.', example: 'El descuento de flujos de caja es el método de valoración más utilizado por analistas.' },
    'Microcrédito': { definition: 'Préstamo de pequeña cuantía concedido a personas com pocos recursos para iniciar un negocio.', example: 'Los microcréditos han ayudado a muchas mujeres a emprender en países en desarrollo.' },
    'Microempresa': { definition: 'Empresa de tamaño muy pequeño, generalmente com menos de diez trabajadores.', example: 'La panadería del barrio é uma microempresa familiar.' },
    'Migración': { definition: 'Movimiento de personas que se desplazan de un lugar a otro por motivos económicos o sociales.', example: 'La migración laboral ayuda a cubrir la falta de mano de obra en ciertos sectores.' },
    'Millonario': { definition: 'Persona que posee una riqueza superior a un millón de unidades monetarias.', example: 'Se convirtió en millonario gracias al éxito de su invención tecnológica.' },
    'Mínimo': { definition: 'Valor más bajo alcanzado por un precio o indicador en un periodo.', example: 'El precio del petróleo alcanzó su mínimo anual durante el confinamiento.' },
    'Minorista': { definition: 'Comerciante que vende productos directamente al consumidor final.', example: 'La tienda de ropa é um minorista que compra a grandes distribuidores.' },
    'Minuta': { definition: 'Borrador de un contrato o cuenta que un profesional presenta por sus servicios.', example: 'El abogado me entregó la minuta por la consulta legal del lunes.' },
    'Mixto': { definition: 'Sistema o activo que combina dos o más naturalezas (como un fondo de renta fija y variable).', example: 'Invertí en un fondo mixto para equilibrar riesgo y rentabilidad.' },
    'Modelo Económico': { definition: 'Representación simplificada de la realidad económica para entender su funcionamiento.', example: 'El modelo económico predice que una bajada de impuestos estimulará el consumo.' },
    'Monetarismo': { definition: 'Teoría económica que enfatiza el papel del gobierno en el control de la cantidad de dinero en circulación.', example: 'El monetarismo sostiene que la inflación es siempre un fenómeno monetario.' },
    'Monetización': { definition: 'Proceso de convertir un activo, servicio o plataforma en una fuente de ingresos.', example: 'La monetización de la red social se basa principalmente en la publicidad.' },
    'Moneda de Reserva': { definition: 'Divisa que los bancos centrales mantienen en grandes cantidades para transacciones internacionales.', example: 'El dólar estadounidense sigue siendo la principal moneda de reserva mundial.' },
    'Moneda Fuerte': { definition: 'Divisa estable que mantiene su valor a lo largo del tiempo y es aceptada globalmente.', example: 'Los inversores buscan refugio en monedas fuertes en tiempos de crisis.' },
    'Moneda Local': { definition: 'Dinero de curso legal emitido y utilizado dentro de un solo país.', example: 'Es recomendable llevar algo de moneda local antes de salir del aeropuerto.' },
    'Monopolio Natural': { definition: 'Situación donde una sola empresa puede producir un bien de forma más eficiente que varias por los altos costes fijos.', example: 'La red de ferrocarriles é um monopolio natural debido al coste de las vías.' },
    'Monopsonio': { definition: 'Situación de mercado donde solo hay un comprador para muchos vendedores.', example: 'El estado é um monopsonio cuando es el único comprador de armamento.' },
    'Mora': { definition: 'Retraso culpable en el cumplimiento de una obligación, especialmente de pago.', example: 'Entrar en mora com el banco conlleva el pago de intereses de demora.' },
    'Morosidad': { definition: 'Situación de falta de pago de las deudas en los plazos acordados.', example: 'La tasa de morosidad bancaria subió tras el aumento del desempleo.' },
    'Muestreo': { definition: 'Técnica estadística de seleccionar una parte representativa de una población para su estudio.', example: 'El muestreo para la encuesta de población activa se realiza trimestralmente.' },
    'Multinacional': { definition: 'Empresa que opera y tiene sedes en varios países del mundo.', example: 'Las empresas multinacionales dominan gran parte del comercio global.' },
    'Multiplicador del Dinero': { definition: 'Efecto por el cual la creación de dinero bancario aumenta la masa monetaria total.', example: 'El multiplicador del dinero depende del coeficiente de caja fijado por el Banco Central.' },
    'Mutua': { definition: 'Sociedad sin ánimo de lucro cuyos asociados comparten riesgos y beneficios (seguros, previsión).', example: 'La mutua de accidentes de trabajo cubre las bajas de nuestros empleados.' },

    // N
    'Neto': { definition: 'Cantidad final que queda después de realizar deducciones (impuestos, gastos).', example: 'Su salario neto es lo que realmente llega a su cuenta bancaria.' },
    'Nicho de Mercado': { definition: 'Segmento específico del mercado com necesidades particulares.', example: 'Vender comida vegana para mascotas é um nicho de mercado.' },
    'Nómina': { definition: 'Documento que detalla el salario y deducciones de un trabajador.', example: 'Revisa tu nómina para ver cuánto pagaste de impuestos.' },
    'Nacionalización': { definition: 'Proceso por el cual el estado asume la propiedad y gestión de una empresa privada.', example: 'La nacionalización de la eléctrica fue una medida para controlar los precios de la energía.' },
    'Nasdaq': { definition: 'Bolsa de valores electrónica de Estados Unidos donde cotizan las principales empresas tecnológicas.', example: 'El Nasdaq subió com fuerza gracias a los resultados de las empresas de inteligencia artificial.' },
    'Neoliberalismo': { definition: 'Corriente económica que defiende la reducción de la intervención del estado y el libre mercado.', example: 'El neoliberalismo ha marcado las políticas económicas de muchos países desde los años 80.' },
    'NIC': { definition: 'Normas Internacionales de Contabilidad; estándares globales para la presentación de estados financieros.', example: 'La empresa adaptó su contabilidad a las NIC para operar en mercados internacionales.' },
    'NIIF': { definition: 'Normas Internacionales de Información Financiera.', example: 'Las NIIF aseguran que los inversores puedan comparar balances de diferentes países.' },
    'Nivel de Precios': { definition: 'Media ponderada de los precios de los bienes y servicios de una economía.', example: 'El nivel de precios se ha mantenido estable gracias a la política monetaria.' },
    'Nivel de Vida': { definition: 'Grado de bienestar o riqueza de una persona o país, medido por su capacidad de consumo.', example: 'El aumento del salario mínimo busca mejorar el nivel de vida de los trabajadores.' },
    'Nominal': { definition: 'Valor expresado en unidades monetarias del momento, sin ajustar por la inflación.', example: 'El crecimiento nominal fue del 5%, pero el real fue de solo el 1% por la inflación.' },
    'Nominativo': { definition: 'Documento o valor que está a nombre de una persona determinada.', example: 'El cheque es nominativo, por lo que solo el beneficiario indicado puede cobrarlo.' },
    'Nota de Crédito': { definition: 'Documento comercial que acredita que una empresa debe dinero a un cliente (por devolución, etc.).', example: 'Me enviaron una nota de crédito por el producto que devolví defectuoso.' },
    'Nota de Débito': { definition: 'Documento comercial que notifica a un cliente un aumento de su deuda.', example: 'El banco emitió una nota de débito por la comisión de descubierto.' },
    'Notario': { definition: 'Funcionario público que da fe legal de contratos y documentos.', example: 'Fuimos al notario para firmar la escritura de compraventa de la casa.' },
    'Novación': { definition: 'Sustitución de una obligación antigua por una nueva que la extingue o modifica.', example: 'Hicimos una novación de la hipoteca para cambiar de interés variable a fijo.' },

    // Ñ
    'Ñapa': { definition: '(Coloquial) Pequeña cantidad extra o propina añadida a una transacción.', example: 'El vendedor me dio una ñapa de fruta por comprar tanto.' },

    // O
    'Oligopolio': { definition: 'Mercado dominado por un pequeño número de vendedores.', example: 'El mercado de telecomunicaciones suele ser un oligopolio.' },
    'Obra Pública': { definition: 'Construcción financiada por el estado para uso de la comunidad (carreteras, hospitales).', example: 'La inversión en obra pública ayuda a reactivar la economía en tiempos de crisis.' },
    'Obsolescencia': { definition: 'Caída en desuso de una máquina o producto por falta de funcionalidad comparada com los nuevos.', example: 'La obsolescencia programada acorta la vida útil de muchos aparatos electrónicos.' },
    'OCDE': { definition: 'Organización para la Cooperación y el Desarrollo Económicos; club de los países más desarrollados.', example: 'España es miembro de la OCDE y sigue sus recomendaciones de política económica.' },
    'OER': { definition: 'Ratio de Gastos de Explotación; porcentaje que representan los gastos operativos sobre los ingresos.', example: 'Reducir el OER es fundamental para mejorar la eficiencia del negocio.' },
    'Oferta Agregada': { definition: 'Cantidad total de bienes y servicios que las empresas de un país están dispuestas a vender.', example: 'La oferta agregada se ve afectada por el coste de la energía y el trabajo.' },
    'Oferta de Dinero': { definition: 'Cantidad total de dinero de curso legal en manos del público y depósitos bancarios.', example: 'Un aumento excesivo de la oferta de dinero puede provocar inflación.' },
    'Oferta Elástica': { definition: 'Oferta que varía mucho ante pequeños cambios en el precio.', example: 'Los productos manufacturados suelen tener una oferta elástica si hay stock.' },
    'Oferta Inelástica': { definition: 'Oferta que apenas cambia aunque varíe el precio (como el petróleo a corto plazo).', example: 'La oferta de vivienda es inelástica porque no se pueden construir casas de un día para otro.' },
    'OIT': { definition: 'Organización Internacional del Trabajo; organismo de la ONU que vela por los derechos laborales.', example: 'La OIT establece las normas mínimas de seguridad en el trabajo a nivel mundial.' },
    'Oligopsonio': { definition: 'Mercado donde hay muy pocos compradores para muchos vendedores.', example: 'Los fabricantes de componentes de avión se enfrentan a un oligopsonio de aerolíneas.' },
    'OMC': { definition: 'Organización Mundial del Comercio; organismo que regula el comercio entre países.', example: 'La OMC media en los conflictos comerciales para evitar guerras de aranceles.' },
    'OPEP': { definition: 'Organización de Países Exportadores de Petróleo; cártel que coordina la producción de crudo.', example: 'Las decisiones de la OPEP influyen directamente en el precio de la gasolina.' },
    'Operación al Contado': { definition: 'Transacción donde el pago y la entrega del bien se realizan simultáneamente.', example: 'La compra de pan é uma operación al contado típica.' },
    'Operación de Capital': { definition: 'Acción que modifica la estructura financiera de una empresa (inversión, emisión de acciones).', example: 'La ampliación de capital é uma operación de capital muy común en startups.' },
    'Oportunidad': { definition: 'Momento favorable para realizar una inversión o negocio com alta probabilidad de éxito.', example: 'La caída de la bolsa fue vista como una oportunidad de compra por los inversores.' },
    'Orden de Compra': { definition: 'Documento que un comprador envía a un vendedor detallando el pedido solicitado.', example: 'Emitimos la orden de compra para recibir el material el próximo lunes.' },
    'Orden de Pago': { definition: 'Instrucción que se da a un banco para que transfiera fondos a un beneficiario.', example: 'Firmé la orden de pago para liquidar la factura del proveedor.' },
    'Oro': { definition: 'Metal precioso utilizado históricamente como reserva de valor y base monetaria.', example: 'El oro suele subir de precio cuando hay mucha incertidumbre en los mercados.' },

    // P
    'Pasivo': { definition: 'Conjunto de deudas y obligaciones de una empresa o persona.', example: 'El pasivo de la empresa incluye préstamos bancarios y cuentas por pagar.' },
    'Patrimonio': { definition: 'Conjunto de bienes, derechos y obligaciones de una persona o empresa.', example: 'Su patrimonio neto aumentó gracias a la subida de sus inversiones.' },
    'Paraíso Fiscal': { definition: 'Territorio que ofrece impuestos muy bajos o nulos a inversores extranjeros.', example: 'Las autoridades luchan contra la evasión de capitales hacia paraísos fiscales.' },
    'PIB': { definition: 'Producto Interno Bruto - valor total de la producción de un país.', example: 'El PIB del país creció un 2% el último trimestre.' },
    'Plusvalía': { definition: 'Aumento del valor de un bien por causas externas.', example: 'El terreno ganó plusvalía tras la construcción del metro cerca.' },
    'Población Activa': { definition: 'Personas en edad de trabajar que tienen empleo o lo buscan activamente.', example: 'La población activa disminuyó debido al envejecimiento.' },
    'Presupuesto': { definition: 'Plan financiero que estima ingresos y gastos para un periodo.', example: 'Hacer un presupuesto mensual te ayuda a controlar tus gastos.' },
    'Prima de Riesgo': { definition: 'Sobreprecio que paga un emisor de deuda com más riesgo frente a uno seguro.', example: 'La prima de riesgo del país subió por la inestabilidad política.' },
    'Préstamo': { definition: 'Dinero que se recibe com la obligación de devolverlo con intereses.', example: 'Pidió un préstamo al banco para comprar un coche.' },
    'Pagaré': { definition: 'Documento en el cual una persona se obliga a pagar a otra una cantidad en una fecha determinada.', example: 'El cliente nos entregó un pagaré a sesenta días por la compra del mobiliario.' },
    'Pago a Cuenta': { definition: 'Cantidad de dinero que se entrega de forma anticipada como parte del pago total.', example: 'Las empresas realizan pagos a cuenta del impuesto de sociedades tres veces al año.' },
    'Pánico Financiero': { definition: 'Situación de alarma colectiva donde los inversores venden masivamente sus activos o retiran depósitos.', example: 'El pánico financiero de 1929 llevó al colapso de las bolsas mundiales.' },
    'Papel Comercial': { definition: 'Instrumento de deuda a corto plazo emitido por empresas para financiarse rápidamente.', example: 'La multinacional emitió papel comercial para cubrir sus necesidades de tesorería este mes.' },
    'Paridad': { definition: 'Relación de igualdad en el valor de dos monedas o activos.', example: 'El euro alcanzó la paridad com el dólar por primera vez en dos décadas.' },
    'Paro': { definition: 'Situación de las personas que teniendo edad y voluntad de trabajar no tienen empleo.', example: 'La reducción del paro es el principal objetivo de las políticas de empleo actuales.' },
    'Partida Doble': { definition: 'Método contable que consiste en registrar cada operación en dos cuentas (debe y haber) para mantener el equilibrio.', example: 'La partida doble es la base de la contabilidad moderna.' },
    'Pasivo Corriente': { definition: 'Deudas y obligaciones de una empresa que deben pagarse en menos de un año.', example: 'El pasivo corriente incluye las facturas de proveedores y los préstamos a corto plazo.' },
    'Patente': { definition: 'Derecho exclusivo concedido por el estado para explotar un invento por un tiempo determinado.', example: 'La farmacéutica registró la patente del nuevo fármaco para proteger su inversión.' },
    'Patrocinio': { definition: 'Convenio por el cual una empresa paga a un evento o persona a cambio de publicidad.', example: 'El patrocinio del equipo de fútbol ayuda a dar visibilidad a la marca internacionalmente.' },
    'Patrón Oro': { definition: 'Sistema monetario que fija el valor de la unidad monetaria en términos de una cantidad determinada de oro.', example: 'El abandono del patrón oro permitió a los países tener políticas monetarias más flexibles.' },
    'Peaje': { definition: 'Tasa que se paga por el derecho a transitar por una vía de comunicación (carretera, canal).', example: 'El coste de los peajes encarece el transporte de mercancías por carretera.' },
    'Pyme': { definition: 'Pequeña y Mediana Empresa; motor principal del empleo en muchos países.', example: 'Las pymes representan más del 90% del tejido empresarial en España.' },
    'Periodo de Carencia': { definition: 'Tiempo durante la vida de un préstamo en el que solo se pagan intereses y no se amortiza capital.', example: 'La hipoteca incluye un periodo de carencia de un año para facilitar los primeros pagos.' },
    'Permuta': { definition: 'Contrato por el cual se intercambia un bien por otro sin que medie dinero de forma principal.', example: 'Realizamos una permuta de terrenos para unificar nuestras fincas agrícolas.' },
    'PIB per cápita': { definition: 'Relación entre el Producto Interior Bruto y el número de habitantes de un país.', example: 'El PIB per cápita é um indicador más preciso del bienestar que el PIB total.' },
    'Pignoración': { definition: 'Acción de dar un bien mueble como garantía (prenda) del cumplimiento de una obligación.', example: 'La pignoración de las acciones sirvió como aval para obtener el crédito.' },
    'Plan de Pensiones': { definition: 'Instrumento de ahorro a largo plazo orientado a complementar la jubilación pública.', example: 'Hago aportaciones mensuales a mi plan de pensiones para desgravar impuestos.' },
    'Planificación': { definition: 'Proceso de establecer objetivos económicos y los medios para alcanzarlos.', example: 'Una buena planificación financiera es vital para el éxito de cualquier negocio.' },
    'Plazo Fijo': { definition: 'Depósito bancario en el que el dinero se mantiene retenido por un tiempo a cambio de un interés pactado.', example: 'Invertí mis ahorros en un plazo fijo a doce meses para no correr riesgos.' },
    'Pliego de Condiciones': { definition: 'Documento que detalla las cláusulas y requisitos de un contrato o licitación pública.', example: 'Leímos atentamente el pliego de condiciones antes de presentar nuestra oferta al ayuntamiento.' },
    'Pobreza': { definition: 'Situación en la que no es posible satisfacer las necesidades físicas y psíquicas básicas por falta de recursos.', example: 'La lucha contra la pobreza extrema é uma prioridad de los organismos internacionales.' },
    'Poder Adquisitivo': { definition: 'Capacidad económica de una persona para comprar bienes y servicios.', example: 'Si los precios suben más que los salarios, el poder adquisitivo de la gente disminuye.' },
    'Póliza': { definition: 'Documento que contiene las condiciones de un contrato de seguro.', example: 'Revisé mi póliza de hogar para ver si cubría los daños eléctricos.' },
    'Política Económica': { definition: 'Conjunto de medidas y estrategias que los gobiernos utilizan para influir en la economía.', example: 'La política económica del país busca reducir el déficit exterior.' },
    'Política Fiscal': { definition: 'Uso del gasto público y los impuestos para influir en la demanda agregada.', example: 'Una política fiscal expansiva suele incluir un aumento de las inversiones públicas.' },
    'Política Monetaria': { definition: 'Acciones de los bancos centrales para gestionar la cantidad de dinero y los tipos de interés.', example: 'La política monetaria restrictiva busca frenar la inflación subiendo los tipos.' },
    'Portafolio': { definition: 'Cartera de inversión; conjunto de activos financieros que posee una persona o entidad.', example: 'He diversificado mi portafolio incluyendo acciones, bonos y algo de oro.' },
    'Posicionamiento': { definition: 'Lugar que ocupa un producto o marca en la mente de los consumidores frente a la competencia.', example: 'El buen posicionamiento de la marca permite vender a precios más altos.' },
    'Posición Corta': { definition: 'Estrategia inversora que consiste en vender un activo esperando que su precio baje para recomprarlo más barato.', example: 'Abrió una posición corta en la tecnológica porque creía que sus acciones estaban sobrevaloradas.' },
    'Posición Larga': { definition: 'Estrategia inversora tradicional de comprar un activo esperando que su precio suba com el tiempo.', example: 'Mantengo una posición larga en fondos indexados desde hace cinco años.' },
    'Precio de Mercado': { definition: 'Valor al que se intercambia un bien o servicio en el mercado de forma libre.', example: 'El precio de mercado del piso es superior a su valor catastral.' },
    'Presión Fiscal': { definition: 'Porcentaje de la renta total de un país que se paga al estado en forma de impuestos.', example: 'Muchos empresarios se quejan de que la presión fiscal es demasiado alta en esta región.' },
    'Privatización': { definition: 'Venta de empresas o servicios públicos al sector privado.', example: 'La privatización de la aerolínea de bandera fue un proceso muy polémico.' },
    'Producción': { definition: 'Actividad económica que consiste en crear bienes y servicios mediante la transformación de recursos.', example: 'La producción industrial creció un tres por ciento el pasado trimestre.' },
    'Productividad': { definition: 'Relación entre la cantidad de productos obtenidos y los recursos utilizados para ello.', example: 'La automatización de la fábrica ha mejorado enormemente la productividad.' },
    'Propiedad Intelectual': { definition: 'Derechos legales sobre las creaciones de la mente, como obras artísticas, marcas y patentes.', example: 'La ley de propiedad intelectual protege a los autores frente al plagio.' },
    'Propiedad Privada': { definition: 'Derecho de las personas y empresas a poseer, controlar y disponer de sus bienes.', example: 'La propiedad privada es uno de los fundamentos de la economía de mercado.' },
    'Proteccionismo': { definition: 'Política económica que busca proteger la industria nacional mediante aranceles y barreras a la importación.', example: 'El proteccionismo excesivo puede provocar represalias comerciales de otros países.' },
    'Proveedor': { definition: 'Empresa o persona que suministra los bienes o servicios necesarios para la actividad de otra.', example: 'Cambiamos de proveedor de energía para reducir los costes de fabricación.' },
    'Provisión': { definition: 'Dinero que una empresa reserva para cubrir un gasto o pérdida probable en el futuro.', example: 'El banco realizó una provisión millonaria para cubrir posibles impagos de hipotecas.' },
    'Punto de Equilibrio': { definition: 'Nivel de ventas en el que los ingresos igualan a los costes totales (no hay ni beneficio ni pérdida).', example: 'Necesitamos vender mil unidades al mes para alcanzar el punto de equilibrio.' },

    // Q
    'Quiebra': { definition: 'Situación jurídica donde una persona o empresa no puede pagar sus deudas.', example: 'La empresa se declaró en quiebra tras años de pérdidas.' },
    'Quita': { definition: 'Acuerdo para reducir el monto de una deuda.', example: 'Los acreedores aceptaron una quita del 30% de la deuda.' },
    'Quórum': { definition: 'Número mínimo de miembros presentes necesario para que una asamblea o junta pueda tomar decisiones válidas.', example: 'La junta no pudo celebrarse por falta de quórum entre los accionistas.' },
    'Quebranto': { definition: 'Pérdida económica o daño patrimonial importante sufrido por una empresa o persona.', example: 'El fraude del contable supuso un grave quebranto para la tesorería de la compañía.' },
    'Queja': { definition: 'Reclamación formal de un cliente por un servicio o producto que no cumple lo esperado.', example: 'Presentamos una queja formal en la oficina del consumidor por el retraso en la entrega.' },
    'Quincena': { definition: 'Periodo de quince días naturales; frecuencia común de pago de salarios en algunos países.', example: 'Cobraré el anticipo de mi salario la próxima quincena.' },
    'Quintil': { definition: 'Estadístico que divide una población en cinco partes iguales (20% cada una) según una variable como la renta.', example: 'Las personas del quintil más pobre reciben el 60% de las ayudas sociales.' },

    // R
    'Recesión': { definition: 'Periodo de disminución de la actividad económica.', example: 'Durante la recesión, muchas empresas dejaron de contratar.' },
    'Renta': { definition: 'Ingreso regular que produce un bien o actividad.', example: 'Vive de la renta de sus apartamentos alquilados.' },
    'Rentabilidad': { definition: 'Capacidad de una inversión para generar beneficios.', example: 'Busco una inversión com alta rentabilidad aunque tenga más riesgo.' },
    'Ratio Precio-Beneficio (PER)': { definition: 'Relación entre el precio de una acción y su beneficio neto por acción.', example: 'Un PER bajo puede indicar que una acción está barata.' },
    'Rentabilidad por Dividendo': { definition: 'Porcentaje que representa el dividendo anual sobre el precio de la acción.', example: 'Esa empresa tiene una alta rentabilidad por dividendo del 5%.' },
    'Reservas': { definition: 'Fondos guardados para contingencias futuras.', example: 'El banco central aumentó sus reservas de oro.' },
    'Riesgo': { definition: 'Probabilidad de que una inversión pierda valor.', example: 'Toda inversión conlleva cierto riesgo.' },
    'Riqueza': { definition: 'Abundancia de bienes y recursos.', example: 'La riqueza nacional se mide no solo por el PIB sino por el bienestar.' },
    'Ráppel': { definition: 'Descuento comercial que se concede a un cliente por alcanzar un determinado volumen de compras en un tiempo.', example: 'El proveedor nos aplicó un ráppel del 2% al superar los cien mil euros de facturación anual.' },
    'Ratio de Liquidez': { definition: 'Indicador que mide la capacidad de una empresa para pagar sus deudas a corto plazo com sus activos más líquidos.', example: 'Un ratio de liquidez inferior a uno puede indicar problemas de tesorería inminentes.' },
    'Ratio de Solvencia': { definition: 'Indicador que mide la capacidad de una empresa para hacer frente a todas sus deudas a largo plazo com sus activos totales.', example: 'El banco exige un ratio de solvencia sólido para conceder el préstamo hipotecario.' },
    'Reajuste': { definition: 'Modificación de precios, salarios o tipos de interés para adaptarlos a nuevas condiciones económicas como la inflación.', example: 'El gobierno anunció un reajuste de las tarifas eléctricas para el próximo trimestre.' },
    'Reaseguro': { definition: 'Contrato por el cual una compañía de seguros cede a otra parte de los riesgos que ha asumido.', example: 'El reaseguro permite a las aseguradoras locales cubrir siniestros de gran magnitud.' },
    'Recaudación': { definition: 'Acción de cobrar o recoger dinero, especialmente de impuestos por parte del estado.', example: 'La recaudación por IVA aumentó significativamente este año debido al consumo navideño.' },
    'Recibo': { definition: 'Documento firmado por quien recibe dinero o bienes para acreditar la entrega.', example: 'Pide siempre el recibo de compra para poder realizar devoluciones en el futuro.' },
    'Reciprocidad': { definition: 'Principio por el cual dos países se conceden mutuamente las mismas ventajas comerciales.', example: 'El acuerdo de reciprocidad eliminó los aranceles para las exportaciones de ambos países.' },
    'Reconocimiento de Deuda': { definition: 'Declaración formal mediante la cual una persona admite que debe una cantidad determinada a otra.', example: 'Firmó un reconocimiento de deuda ante notario para asegurar el pago del préstamo personal.' },
    'Reconversión': { definition: 'Proceso de modernización de un sector industrial para hacerlo competitivo o adaptarlo a nuevas tecnologías.', example: 'La reconversión industrial de los astilleros fue un proceso socialmente doloroso.' },
    'Reembolso': { definition: 'Devolución de una cantidad de dinero a quien la pagó previamente.', example: 'Solicité el reembolso del billete de avión tras la cancelación del vuelo por mal tiempo.' },
    'Refinanciación': { definition: 'Sustitución de una deuda existente por una nueva com condiciones diferentes (plazo, interés).', example: 'La refinanciación de la deuda permitió a la empresa evitar la quiebra inmediata.' },
    'Reforma Fiscal': { definition: 'Cambio profundo en el sistema de impuestos de un país para aumentar la recaudación o mejorar la equidad.', example: 'La reforma fiscal bajó el IRPF para las rentas medias y subió los impuestos al lujo.' },
    'Refugio Seguro': { definition: 'Activo que mantiene o aumenta su valor durante tiempos de incertidumbre o crisis (como el oro).', example: 'En momentos de guerra, los inversores corren hacia refugios seguros como el franco suizo.' },
    'Registro de la Propiedad': { definition: 'Institución pública donde se inscriben los actos y contratos relativos a la propiedad de bienes inmuebles.', example: 'Antes de comprar el piso, pedí una nota simple al Registro de la Propiedad para ver si tenía cargas.' },
    'Regulación': { definition: 'Conjunto de normas dictadas por el estado para controlar el funcionamiento de un mercado o actividad.', example: 'La nueva regulación bancaria exige a las entidades tener más capital de reserva.' },
    'Relación de Intercambio': { definition: 'Relación entre los precios de las exportaciones e importaciones de un país.', example: 'La caída del precio del petróleo mejoró la relación de intercambio de los países importadores.' },
    'Remesa': { definition: 'Envío de dinero que realizan los migrantes a sus familias en su país de origen.', example: 'Las remesas são una fuente vital de divisas para muchos países en desarrollo.' },
    'Rendimiento': { definition: 'Beneficio o utilidad que produce una inversión o actividad económica.', example: 'Este fondo de inversión ha dado un rendimiento anual del ocho por ciento.' },
    'Rentas Bajas': { definition: 'Personas o familias com ingresos reducidos que suelen recibir ayudas sociales.', example: 'El bono social eléctrico está destinado exclusivamente a consumidores con rentas bajas.' },
    'Rentas Medias': { definition: 'Segmento mayoritario de la población com ingresos que les permiten cubrir necesidades básicas y algo de ahorro.', example: 'La subida del IVA afecta proporcionalmente más a las rentas medias que a las altas.' },
    'Rescate': { definition: 'Acción de salvar a una empresa o país de la quiebra mediante asistencia financiera pública o privada.', example: 'El rescate bancario de 2012 costó miles de millones de euros a los contribuyentes.' },
    'Responsabilidad Civil': { definition: 'Obligación legal de reparar el daño causado a otra persona o sus bienes.', example: 'El seguro de responsabilidad civil cubrió los gastos del accidente en el local.' },
    'Retención': { definition: 'Cantidad de dinero que se detrae de un pago (salario, intereses) para ingresarla en hacienda como pago a cuenta.', example: 'La retención del IRPF en mi nómina es del quince por ciento.' },
    'Retorno de Inversión (ROI)': { definition: 'Métrica que mide la rentabilidad de una inversión comparando el beneficio obtenido com el capital invertido.', example: 'El ROI de nuestra campaña publicitaria fue excelente: por cada euro invertido ganamos cinco.' },
    'Retribución': { definition: 'Pago o recompensa que se recibe por un trabajo o servicio prestado.', example: 'La retribución flexible permite cobrar parte del sueldo en vales de comida o seguro médico.' },
    'Revaluación': { definition: 'Aumento oficial del valor de una moneda frente a otras o frente al oro.', example: 'La revaluación de la moneda local abarató las importaciones pero perjudicó a los exportadores.' },
    'Riesgo Cambiario': { definition: 'Posibilidad de pérdida debida a las variaciones en el tipo de cambio de las monedas.', example: 'Las empresas que exportan a Estados Unidos se enfrentan al riesgo cambiario del dólar.' },
    'Riesgo de Mercado': { definition: 'Riesgo de que el valor de una inversión disminuya debido a cambios generales en el mercado (tipos de interés, precios).', example: 'El riesgo de mercado es inevitable si inviertes en renta variable.' },
    'Riesgo Sistémico': { definition: 'Probabilidad de que el fallo de una entidad o mercado provoque un colapso en todo el sistema financiero.', example: 'La caída de Lehman Brothers provocó un riesgo sistémico que afectó a todo el mundo.' },
    'Royalty': { definition: 'Canon; pago que se realiza por el uso de una propiedad intelectual o explotación de recursos naturales.', example: 'El escritor recibe un royalty del diez por ciento por cada libro vendido.' },

    // S
    'Salario': { definition: 'Dinero que recibe un trabajador por su labor.', example: 'Recibe su salario a final de mes.' },
    'Saldo': { definition: 'Diferencia entre el debe y el haber; cantidad disponible en una cuenta.', example: 'Su saldo bancario es positivo.' },
    'Sector Primario': { definition: 'Sector de la economía que obtiene productos directamente de la naturaleza (agricultura, pesca).', example: 'El sector primario emplea al 10% de la población.' },
    'Seguro': { definition: 'Contrato para protegerse contra pérdidas financieras.', example: 'Es obligatorio tener un seguro de coche.' },
    'Solvencia': { definition: 'Capacidad para hacer frente a las deudas.', example: 'El banco demostró su solvencia en las pruebas de estrés.' },
    'Subvención': { definition: 'Ayuda económica del gobierno a empresas o personas.', example: 'Recibieron una subvención para instalar paneles solares.' },
    'Superávit': { definition: 'Situación donde los ingresos superan a los gastos.', example: 'El país logró un superávit comercial este año.' },
    'Suspensión de Pagos': { definition: 'Situación legal de una empresa que no puede pagar sus deudas por falta de liquidez temporal.', example: 'La empresa solicitó la suspensión de pagos para intentar negociar com los bancos.' },
    'Segmentación de Mercado': { definition: 'División del mercado en grupos más pequeños de consumidores com características similares.', example: 'La segmentación de mercado nos permitió dirigir el producto solo a jóvenes deportistas.' },
    'Seguro de Vida': { definition: 'Contrato por el cual el asegurador paga una cuantía a los beneficiarios tras el fallecimiento del asegurado.', example: 'Contrató un seguro de vida al pedir la hipoteca para proteger a su familia.' },
    'Servicio': { definition: 'Bien intangible que consiste en realizar una actividad para satisfacer una necesidad o deseo humano.', example: 'El sector servicios es el que más peso tiene en la economía española.' },
    'Servicios Financieros': { definition: 'Servicios prestados por bancos y entidades para el manejo de dinero e inversiones.', example: 'Las aplicaciones móviles han facilitado el acceso a servicios financieros desde cualquier lugar.' },
    'Sindicato': { definition: 'Asociación de trabajadores para la defensa y promoción de sus intereses laborales y económicos.', example: 'El sindicato negoció com la patronal el nuevo convenio colectivo del sector.' },
    'Sistema Económico': { definition: 'Forma en que una sociedad organiza la producción y distribución de bienes y servicios.', example: 'Existen diferentes sistemas económicos, como el capitalismo de mercado o la economía planificada.' },
    'Sistema Monetario': { definition: 'Conjunto de normas e instituciones que regulan el uso de la moneda y el crédito en un país o zona.', example: 'El euro es la unidad básica del sistema monetario de la Unión Europea.' },
    'Soberanía': { definition: 'Poder político supremo que corresponde a un estado independiente sobre su territorio y población.', example: 'La soberanía económica permite a los países decidir su propia política de impuestos.' },
    'Sociedad Anónima (S.A.)': { definition: 'Empresa cuyo capital está dividido en acciones y donde los socios solo responden com el capital aportado.', example: 'La mayoría de las grandes empresas que cotizan en bolsa são sociedades anónimas.' },
    'Sociedad de Responsabilidad Limitada (S.R.L.)': { definition: 'Empresa com capital dividido en participaciones, ideal para negocios pequeños y medianos por su menor exigencia de capital.', example: 'Registramos nuestro pequeño taller como una sociedad de responsabilidad limitada.' },
    'Sociedad de Valores': { definition: 'Entidad financiera autorizada para operar en los mercados de valores tanto por cuenta propia como ajena.', example: 'Realicé la compra de las acciones a través de una sociedad de valores de confianza.' },
    'Sociedad Holding': { definition: 'Empresa cuya actividad principal es tener acciones de otras para controlarlas.', example: 'La sociedad holding centraliza la gestión de todas las marcas de ropa del grupo.' },
    'Sostenibilidad': { definition: 'Capacidad de mantener la actividad económica a largo plazo sin agotar los recursos naturales o dañar el medio ambiente.', example: 'La sostenibilidad es ahora un criterio clave para recibir fondos de inversión internacionales.' },
    'Spread': { definition: 'Diferencial entre el precio de compra y el de venta de un activo, o entre dos tipos de interés.', example: 'El spread del bono español frente al alemán é um indicador del riesgo país.' },
    "Standard & Poor's": { definition: 'Agencia de calificación de riesgos estadounidense que puntúa la solvencia de empresas y estados.', example: "Standard & Poor's mantuvo la nota de excelente para la deuda de los Países Bajos." },
    'Stock Options': { definition: 'Derecho que se da a empleados para comprar acciones de la empresa a un precio fijo en el futuro.', example: 'Los directivos de la tecnológica recibieron stock options como incentivo por objetivos.' },
    'Subasta': { definition: 'Venta pública de bienes al mejor postor basándose en la competencia de precios.', example: 'Hacienda sacó a subasta los coches embargados para recuperar parte de la deuda.' },
    'Suministro': { definition: 'Provisión de víveres o servicios necesarios para una actividad o población.', example: 'Garantizar el suministro de energía es estratégico para la seguridad nacional.' },
    'Superávit Comercial': { definition: 'Situación en la que las exportaciones de un país superan a sus importaciones.', example: 'Alemania ha tenido un superávit comercial constante durante las últimas décadas.' },
    'Superávit Fiscal': { definition: 'Ocurre cuando los ingresos del estado superan a sus gastos en un ejercicio.', example: 'El gobierno usará el superávit fiscal para reducir la deuda pública acumulada.' },
    'Swap': { definition: 'Contrato financiero por el cual dos partes intercambian flujos de dinero o beneficios.', example: 'Usamos un swap de tipos de interés para pasar nuestra deuda de variable a fija.' },
    'SWIFT': { definition: 'Sistema global de mensajería financiera que permite realizar transferencias bancarias internacionales de forma segura.', example: 'Sin el código SWIFT del banco no es posible realizar ingresos desde el extranjero.' },

    // T
    'Tasa de Interés': { definition: 'Porcentaje que se paga por un préstamo o se recibe por un depósito.', example: 'La tasa de interés subió al 4%.' },
    'Tasa de Desempleo': { definition: 'Porcentaje de la población activa que no tiene empleo.', example: 'La tasa de desempleo bajó al 3.5%.' },
    'Tipo de Cambio': { definition: 'Precio de una moneda en términos de otra.', example: 'El tipo de cambio euro-dólar favorece a los exportadores.' },
    'Título': { definition: 'Documento que acredita un derecho o propiedad.', example: 'Tiene un título de propiedad de la casa.' },
    'Tributo': { definition: 'Pago obligatorio al estado (impuestos, tasas).', example: 'Debes pagar tus tributos puntualmente.' },
    'Táctica': { definition: 'Método o sistema para ejecutar o conseguir algo a corto plazo dentro de una estrategia.', example: 'La táctica de rebajar precios ayudó a liquidar el stock sobrante.' },
    'Talón': { definition: 'Cheque; documento que permite a una persona retirar dinero de una cuenta bancaria propia o ajena.', example: 'Me pagaron el trabajo com un talón conformado por el banco.' },
    'Tasa de Actividad': { definition: 'Porcentaje de la población en edad de trabajar que está empleada o busca empleo activamente.', example: 'La tasa de actividad femenina ha crecido notablemente en la última década.' },
    'Tasa de Cobertura': { definition: 'Porcentaje de las importaciones que pueden pagarse com las exportaciones de un país.', example: 'Una tasa de cobertura superior al cien por cien indica un superávit comercial.' },
    'Tasa de Crecimiento': { definition: 'Porcentaje en el que aumenta o disminuye una variable económica (como el PIB) en un tiempo.', example: 'La tasa de crecimiento de la economía se estancó debido a la crisis energética.' },
    'Tasa de Descuento': { definition: 'Tipo de interés utilizado para calcular el valor actual de los cobros o pagos futuros.', example: 'Aplicamos una tasa de descuento del diez por ciento para valorar el proyecto de inversión.' },
    'Tasa de Inflación': { definition: 'Porcentaje que mide el aumento generalizado de los precios en un periodo.', example: 'La tasa de inflación interanual alcanzó máximos históricos el pasado mes.' },
    'Tasa Interna de Retorno (TIR)': { definition: 'Tipo de interés que hace que el valor actual neto de una inversión sea igual a cero.', example: 'Solo aprobamos proyectos cuya TIR sea superior al coste de financiación.' },
    'Tasación': { definition: 'Estimación del valor económico de un bien realizada por un experto.', example: 'La tasación de la vivienda é um paso previo obligatorio para la concesión de la hipoteca.' },
    'Tecnología': { definition: 'Conjunto de conocimientos y herramientas aplicados a la producción de bienes y servicios.', example: 'La inversión en tecnología es clave para mejorar la competitividad de las empresas.' },
    'Teletrabajo': { definition: 'Actividad laboral que se realiza a distancia utilizando medios telemáticos.', example: 'El teletrabajo ha permitido una mejor conciliación entre la vida familiar y laboral.' },
    'Tendencia': { definition: 'Dirección general en la que se mueve un mercado o indicador a lo largo del tiempo.', example: 'La tendencia del mercado de valores es claramente alcista desde principios de año.' },
    'Tenedor': { definition: 'Poseedor legítimo de un título valor (letra, pagaré, acción).', example: 'El tenedor del cheque puede cobrarlo en cualquier oficina de la entidad emisora.' },
    'Teoría de Juegos': { definition: 'Área de la economía que estudia las decisiones óptimas entre agentes que interactúan entre sí.', example: 'La teoría de juegos se aplica para entender las guerras de precios en un oligopolio.' },
    'Tesorería': { definition: 'Departamento de una empresa que gestiona los cobros, pagos y la liquidez diaria.', example: 'La tesorería de la compañía está en niveles mínimos debido al retraso en los pagos de los clientes.' },
    'Tesoro Público': { definition: 'Organismo del estado que gestiona la deuda pública y las finanzas nacionales.', example: 'El Tesoro Público emitió letras a tres meses com un interés muy atractivo.' },
    'Testamento': { definition: 'Documento legal en el que una persona dispone el reparto de sus bienes tras su fallecimiento.', example: 'Hizo un testamento ante notario para evitar conflictos entre sus herederos.' },
    'Tipo Impositivo': { definition: 'Porcentaje que se aplica a la base imponible para calcular la cuota tributaria.', example: 'El tipo impositivo del IVA general en España es del veintiuno por ciento.' },
    'Titularización': { definition: 'Proceso de convertir activos poco líquidos (como hipotecas) en títulos valores negociables.', example: 'La titularización de activos permite a los bancos liberar capital para nuevos préstamos.' },
    'Trabajo': { definition: 'Esfuerzo humano aplicado a la producción de bienes y servicios.', example: 'El trabajo es uno de los tres factores fundamentales de producción.' },
    'Transacción': { definition: 'Operación comercial que consiste en el intercambio de bienes o servicios por dinero.', example: 'La transacción se completó tras la confirmación de la transferencia bancaria.' },
    'Transferencia': { definition: 'Operación por la cual una persona ordena a su banco el envío de dinero a otra cuenta.', example: 'Recibí una transferencia de mis padres para pagar la matrícula de la universidad.' },
    'Transparencia': { definition: 'Principio de claridad y acceso a la información en la gestión económica y pública.', example: 'La transparencia financiera es esencial para generar confianza en los inversores.' },
    'Traspaso': { definition: 'Cesión a un tercero de un contrato de arrendamiento de un local de negocio a cambio de un precio.', example: 'Se anuncia el traspaso de la cafetería por jubilación del propietario actual.' },
    'Trueque': { definition: 'Intercambio directo de bienes o servicios sin la mediación de dinero.', example: 'El trueque fue la forma primitiva de comercio antes de la invención de la moneda.' },

    // U
    'Umbral de Rentabilidad': { definition: 'Punto donde los ingresos igualan a los costos (punto de equilibrio).', example: 'La empresa alcanzará el umbral de rentabilidad en su segundo año.' },
    'Utilidad': { definition: 'Beneficio o ganancia neta; también satisfacción que da un bien.', example: 'La utilidad neta fue mayor a la esperada.' },
    'UE (Unión Europea)': { definition: 'Comunidad política de derecho constituida en régimen sui géneris de organización internacional nacida para propiciar y acoger la integración y gobernanza en común de los Estados y los pueblos de Europa.', example: 'La UE facilita el libre comercio entre sus estados miembros.' },
    'UGT': { definition: 'Unión General de Trabajadores; organización sindical obrera española.', example: 'La UGT participó en las negociaciones del nuevo salario mínimo.' },
    'Unidad de Cuenta': { definition: 'Función del dinero que permite expresar el valor de todos los bienes y servicios en una unidad común.', example: 'El euro actúa como unidad de cuenta en toda la eurozona.' },
    'Unidad Monetaria': { definition: 'Tipo de moneda que utiliza un país o territorio para sus transacciones.', example: 'El franco suizo é uma de las unidades monetarias más estables del mundo.' },
    'Unificación': { definition: 'Proceso de fundir en una sola varias entidades o sistemas económicos o monetarios.', example: 'La unificación monetaria alemana fue un reto económico sin precedentes.' },
    'Unión Aduanera': { definition: 'Área de libre comercio que además establece un arancel exterior común frente a terceros países.', example: 'La Unión Aduanera de la UE permite que las mercancías circulen sin controles fronterizos internos.' },
    'Unión Económica': { definition: 'Mercado común que además implica la armonización de las políticas económicas de los estados miembros.', example: 'La Unión Económica y Monetaria es el paso más avanzado de la integración europea.' },
    'Unión Monetaria': { definition: 'Acuerdo entre dos o más países para compartir la misma moneda.', example: 'La Unión Monetaria permite reducir los costes de transacción en el comercio internacional.' },
    'Usura': { definition: 'Cobro de intereses excesivamente altos en un préstamo, a menudo considerados ilegales.', example: 'El tribunal anuló el contrato de la tarjeta de crédito por considerarlo usura.' },
    'Usuario': { definition: 'Persona que utiliza habitualmente un servicio o producto.', example: 'El usuario final debe estar en el centro de cualquier estrategia de marketing.' },

    // V
    'Volatilidad': { definition: 'Medida de la variación del precio de un activo.', example: 'Las criptomonedas tienen alta volatilidad.' },
    'Vacaciones': { definition: 'Periodo de descanso retribuido al que tienen derecho los trabajadores tras un tiempo de servicio.', example: 'Las vacaciones pagadas são una conquista social fundamental del siglo XX.' },
    'Vale': { definition: 'Documento que se entrega a una persona para que pueda recibir un bien o servicio determinado o un descuento.', example: 'La empresa entregó vales de comida a sus empleados como parte de la retribución.' },
    'Valor de Mercado': { definition: 'Precio que se pagaría por un activo en un mercado abierto y competitivo.', example: 'El valor de mercado de la empresa se disparó tras el anuncio de la patente.' },
    'Valor de Reposición': { definition: 'Coste de volver a adquirir o fabricar un bien com las mismas características en el momento actual.', example: 'El seguro pagó el valor de reposición de la maquinaria tras el incendio.' },
    'Valor Nominal': { definition: 'Valor que figura de forma explícita en un título o documento, sin tener en cuenta la inflación o el valor real.', example: 'El valor nominal de la acción es de un euro, aunque cotiza a diez.' },
    'Valor Real': { definition: 'Valor de un bien o renta expresado en términos de poder adquisitivo, ajustado por la inflación.', example: 'El salario real ha bajado este año pese a que el nominal ha subido ligeramente.' },
    'Valor Residual': { definition: 'Valor que tiene un activo al final de su vida útil, después de haber sido amortizado.', example: 'Estimamos un valor residual del cinco por ciento para los ordenadores tras cuatro años de uso.' },
    'Valoración': { definition: 'Proceso de asignar un valor económico a algo basándose en criterios técnicos y de mercado.', example: 'La valoración de la startup para la ronda de inversión superó todas las expectativas.' },
    'Variable': { definition: 'Magnitud económica que puede cambiar de valor a lo largo del tiempo (como el PIB, el empleo o los precios).', example: 'Los tipos de interés são una variable clave en la política monetaria.' },
    'Vendedor': { definition: 'Persona o entidad que traspasa la propiedad de un bien a cambio de un precio.', example: 'El vendedor está obligado a entregar el producto en las condiciones pactadas.' },
    'Venta al Mayor': { definition: 'Venta de mercancías en grandes cantidades a otros comerciantes o distribuidores.', example: 'Nuestra empresa se dedica exclusivamente a la venta al mayor de materiales de construcción.' },
    'Venta al Menor': { definition: 'Comercio minorista; venta directa de productos al consumidor final.', example: 'La red de tiendas de venta al menor es fundamental para llegar al gran público.' },
    'Verificación': { definition: 'Comprobación de la veracidad o exactitud de cuentas, datos o procesos económicos.', example: 'La auditoría externa realizó una verificación exhaustiva de los balances anuales.' },
    'Vida Útil': { definition: 'Periodo durante el cual se espera que un activo sea productivo o funcional para la empresa.', example: 'La vida útil de este camión de reparto es de aproximadamente ocho años.' },
    'Virtual': { definition: 'Actividad o bien que no tiene presencia física y se desarrolla a través de medios informáticos.', example: 'La moneda virtual ha ganado popularidad como medio de intercambio en internet.' },
    'Visión': { definition: 'Declaración de las metas y aspiraciones a largo plazo de una empresa u organización.', example: 'Nuestra visión es ser líderes globales en energías renovables para el año 2030.' },
    'Vivienda': { definition: 'Bien inmueble destinado a la habitación de personas; es uno de los principales activos de ahorro de las familias.', example: 'La inversión en vivienda suele considerarse segura a largo plazo en este país.' },
    'Volumen de Negocio': { definition: 'Cifra total de ventas o ingresos que genera una empresa en un ejercicio fiscal.', example: 'A pesar de la crisis, el volumen de negocio de la compañía aumentó un cinco por ciento.' },

    // W
    'Warrant': { definition: 'Producto financiero que da derecho a comprar o vender un activo a un precio fijo.', example: 'Los warrants são instrumentos complejos para inversores avanzados.' },
    'Wall Street': { definition: 'Centro financiero de Nueva York donde se encuentra la bolsa de valores más importante del mundo.', example: 'Wall Street reaccionó com optimismo a las noticias sobre los tipos de interés.' },
    'Web 3.0': { definition: 'Evolución de internet basada en la descentralización, las tecnologías blockchain y la propiedad del usuario.', example: 'La Web 3.0 promete cambiar la forma en que interactuamos com las finanzas digitales.' },
    'Welfare': { definition: 'Estado de bienestar; sistema que busca garantizar niveles básicos de salud, educación y renta para todos los ciudadanos.', example: 'El sistema de welfare europeo se financia principalmente a través de impuestos progresivos.' },

    // Y
    'Yield (Rendimiento)': { definition: 'Rentabilidad de una inversión expresada en porcentaje.', example: 'El yield de este bono es del 5%.' },
    'Yacimiento': { definition: 'Acumulación natural de minerales o hidrocarburos que puede ser explotada económicamente.', example: 'El descubrimiento de un nuevo yacimiento de litio impulsó la economía de la región.' },

    // Z
    'Zona Franca': { definition: 'Área geográfica com beneficios fiscales para atraer inversión.', example: 'La empresa se instaló en una zona franca para pagar menos impuestos.' },
    'Zafra': { definition: 'Cosecha de la caña de azúcar o época en que se recolecta; término agrícola com gran impacto económico regional.', example: 'La economía local depende enteramente del éxito de la zafra anual.' },
    'Zona': { definition: 'Área geográfica delimitada com características económicas o administrativas comunes.', example: 'Esta zona ha sido declarada de especial interés para la inversión tecnológica.' },
};
